// 자동 생성 (tools/extract_spd_items.py): 게임 items 폴더의 모든 아이템 — game/shattered-pixel-dungeon 기준 (mod2: mod-2 저장소에만 있는 것)
// p: spd: 뒤에 쓰는 경로, sub: 세부 종류, n/d: 한국어 이름·설명, img: ItemSpriteSheet 상수, t: 티어
PDM.SPD_ITEM_GROUPS = {"misc":[{"p":"Waterskin","sub":"","n":"가죽 물통","d":"코르크로 입구를 봉한 가죽 물통입니다.","img":"WATERSKIN"},{"p":"Gold","sub":"","n":"금화","d":"금화가 쌓인 더미입니다. 나중에 상점에서 사용할 수 있도록 금화를 모으십시오.","img":"GOLD"},{"p":"Honeypot","sub":"","n":"꿀단지","d":"이 커다란 꿀단지는 꿀만으로 채워진 대신, 거대한 벌을 담고 있습니다! 벌들은 보통 무리를 지어 벌집에서 살기 때문에, 이 단지는 벌을 가두기 위한 함정일 수도 있습니다. 벌은 단지 안의 꿀에 만족한 모습이지만, 당신이 쳐다보면 조심스럽게 윙윙거리는 소리를 들을 수 있습니다.","img":"HONEYPOT"},{"p":"KingsCrown","sub":"","n":"드워프 제왕의 왕관","d":"마지막 드워프 제왕의 왕관으로, 엄청난 마법 에너지로 빛나고 있습니다.\\n\\n이 왕관을 착용하면 입고 있는 방어구에 마법을 전달해 _고유한 능력을 가진 전설 방어구_로 변화시킵니다. 전설 방어구는 원본 방어구의 모든 특성을 유지합니다.","img":"CROWN"},{"p":"BrokenSeal","sub":"","n":"부러진 인장","d":"갑옷에 붙여 용맹함을 자랑할 수 있는 밀랍 인장입니다. 중앙에는 보호의 룬이 새겨져 있고, 한 가운데에 갈라진 틈이 있습니다.\\n\\n고향의 보물인 이 인장은 전사의 인내력을 강화합니다. 인장이 붙은 갑옷을 입은 전사는 체력이 절반 이하로 감소할 때 자동으로 대량의 보호막을 얻습니다.\\n\\n이 인장은 _갑옷에 붙일 수 있으며, 여러 갑옷에 옮겨 붙일 수 있습니다._ 인장이 붙은 채로 방어구를 강화하면 인장을 1회까지 강화할 수 있으며, 강화된 인장이 붙은 방어구는 1만큼의 추가 강화 수치를 얻습니다.","img":"SEAL"},{"p":"Stylus","sub":"","n":"신비한 바늘","d":"이 신비한 바늘은 어두운 색의 단단한 돌로 만들어졌습니다. 이 바늘을 사용하여 방어구에 마법 상형문자를 새길 수 있습니다만, 어떠한 상형문자가 새겨지는지 알 수 없으며 오직 바늘이 새기는 대로 결정됩니다.","img":"STYLUS"},{"p":"ArcaneResin","sub":"","n":"신비한 송진","d":"이 고운 가루는 보라색과 하얀색으로 은은하게 빛나고 있습니다. 이 가루를 마법 막대에 바르면 막대의 마력을 증폭시켜 강화 수치가 증가합니다!\\n\\n마법 막대를 강화할 때 이전의 강화 수치에 따라 1,2,3개의 송진을 소모합니다. 마법 막대는 송진으로 최대 +3까지 강화할 수 있습니다.\\n\\n(강화의 주문서와 같은) 다른 강화 효과가 적용될 경우 송진 강화가 덮어씌워지며, 마법사의 지팡이에 마법 막대를 융합할 때 송진으로 얻은 강화 수치는 무시합니다.","img":"ARCANE_RESIN"},{"p":"Ankh","sub":"","n":"앙크","d":"영생을 상징하는 고대의 물건으로 소유자의 생명을 되살릴 수 있는 능력이 있습니다. 부활하면서 대부분의 아이템이 당신이 죽은 곳에 떨어지지만, 다시 돌아가서 획득할 수 있습니다. 가득 찬 물통을 사용해 앙크를 축복하여 강화할 수 있습니다.","img":"ANKH"},{"p":"LiquidMetal","sub":"","n":"액체 금속","d":"이 마법 액체는 투척 무기의 금이 가거나 찢어진 부분에 스며들어, 투척 무기를 완벽한 상태로 복원합니다! 투척 무기 세트에 무기가 하나 없지만 다른 부분은 완전히 수리된 경우, 액체 금속을 사용하여 세트에서 누락된 무기를 교체할 수도 있습니다!\\n\\n1 티어 무기는 완전히 수리하기 위해 10개의 액체 금속이 필요하며, 5 티어 무기는 30개의 액체 금속이 필요합니다. 투척 무기를 강화할 때마다 필요한 액체 금속의 양이 33%씩 증가합니다.\\n\\n액체 금속은 특수 다트의 내구도는 수리할 수 없습니다.","img":"LIQUID_METAL"},{"p":"EnergyCrystal","sub":"","n":"에너지 결정","d":"연금술 에너지로 채워진 작은 마법 수정의 집합입니다.\\n\\n이 수정들은 연금술 레시피에서 흔하게 사용되는 재료이며, 연금술 솥에서 소모품을 분해해 얻을 수도 있습니다.","img":"ENERGY"},{"p":"Amulet","sub":"","n":"옌더의 부적","d":"옌더의 부적은 인간 또는 드워프 사회에서 알려진 가장 강력한 유물입니다. 부적에 박힌 반짝거리는 수정들은 불가사의하면서도 경이로운 힘을 가지고 있습니다.","img":"AMULET"},{"p":"Dewdrop","sub":"","n":"이슬","d":"수정같이 깨끗한 이슬입니다.\\n\\n이 장소의 마법의 영향으로 인해, 순수한 물은 약한 회복 효과를 가집니다.","img":"DEWDROP"},{"p":"LostBackpack","sub":"","n":"잃어버린 배낭","d":"당신이 잃어버린 배낭입니다. 배낭을 주워 당신이 잃어버린 것들을 되찾으세요!","img":"BACKPACK"},{"p":"TengusMask","sub":"","n":"텐구의 가면","d":"이 가면은 텐구 암살자가 죽으면서 그의 얼굴에서 떨어져 나왔습니다. 강력한 마법의 힘이 뿜어져 나오는 것이 느껴집니다. 텐구 암살자의 힘의 원천이었을까요?\\n\\n이 가면을 쓰면 엄청난 힘이 당신에게 전해져, _영웅의 세부 직업을 선택_할 수 있습니다.\\n\\n어떤 세부 직업을 선택하시겠습니까?","img":"MASK"},{"p":"Torch","sub":"","n":"횃불","d":"모험가의 필수 장비입니다. 던전이 어두워진다면, 횃불을 밝혀 길을 찾으십시오.","img":"TORCH"}],"bomb":[{"p":"bombs.ArcaneBomb","sub":"","n":"비전 폭탄","d":"이 폭탄은 마법의 힘과 융합되었으며, 폭탄이 폭발하면 구의 몸집 불리기 공격과 비슷하게 주변 2타일 이내에 있는 모든 대상에게 _%1$d-%2$d_의 마법 피해를 입히는 강력한 폭발을 일으킵니다.","img":"ARCANE_BOMB"},{"p":"bombs.FrostBomb","sub":"","n":"서리 폭탄","d":"폭발이 더 넓게 퍼지도록 개조된 폭탄입니다. 폭탄이 폭발하면 주변 2타일 이내에 있는 모든 대상에게 _%1$d-%2$d_의 피해를 입히고, 동시에 범위 내의 모든 지역을 지속적으로 얼어붙게 하는 냉기 돌풍으로 뒤덮을 것입니다.","img":"FROST_BOMB"},{"p":"bombs.FlashBangBomb","sub":"","n":"섬광탄","d":"이 폭탄은 순간적으로 엄청난 빛과 소리를 뿜어냄과 동시에 전기를 방출하도록 개조되었습니다.  폭탄이 폭발하면 주변 2타일 내에 있는 모든 대상에게 _%1$d-%2$d_의 피해를 입히고, 동시에 전기로부터 25%%의 추가 피해를 받게 만들 것이며, 동시에 10턴 동안  기절시킬 것입니다.","img":"FLASHBANG"},{"p":"bombs.Noisemaker","sub":"","n":"소음 폭탄","d":"이 폭탄은 도화선에 불을 붙이면 반복적으로 시끄러운 소음을 내며 타 들어가도록 개조되었습니다. 누군가가 폭탄을 건드리면 폭발하며 주변 2타일 이내에 있는 모든 대상에게 _%1$d-%2$d_의 피해를 입힐 것입니다!","img":"NOISEMAKER"},{"p":"bombs.HolyBomb","sub":"","n":"신성 폭탄","d":"이 폭탄은 넓은 지역에 신성한 빛의 섬광을 방출하도록 개조되었습니다. 폭탄이 폭발하면 주변 2타일 이내에 있는 모든 대상에게 _%1$d-%2$d_의 피해를 입히고, 언데드와 악마는 이 빛으로부터 50%%의 추가 피해를 받습니다.","img":"HOLY_BOMB"},{"p":"bombs.WoollyBomb","sub":"","n":"양 폭탄","d":"이 폭탄은 주변에 마법 양떼를 소환하도록 개조되었습니다. 폭탄이 폭발하면 주변 2타일 이내에 있는 모든 대상에게 _%1$d-%2$d_의 피해를 입히고, 동시에 마법의 양이 아주 긴 시간 동안 이동을 막고 있을 것입니다! 그러나 강력한 적들이 있는 곳에서는 양이 오래 버틸 수 없으며, 또 당신은 양에게 접촉해 직접 마법을 해제하고 더 빨리 사라지게 만들 수 있습니다.","img":"WOOLY_BOMB"},{"p":"bombs.SmokeBomb","sub":"","n":"연막탄","d":"폭발이 발생함과 동시에 두꺼운 가스 구름을 살포하도록 개조된 폭탄입니다. 폭탄이 폭발하면 주변 2타일 이내에 있는 모든 대상에게 _%1$d-%2$d_의 피해를 입히고, 동시에 범위 내의 모든 지역을 짙은 안개로 뒤덮을 것입니다.","img":"SMOKE_BOMB"},{"p":"bombs.RegrowthBomb","sub":"","n":"재성장의 폭탄","d":"이 폭탄은 피해를 입히는 대신 주변 3타일 범위에 생명의 영약을 흩뿌리도록 개조되었습니다. 폭탄이 폭발하면 범위 내에 있는 모든 지역에 잔디와 식물이 빠르게 자라나게 되며, 당신 혹은 아군이 폭발 범위 내에 있을 경우 치유 물약을 마신 것처럼 치유될 것입니다.","img":"REGROWTH_BOMB"},{"p":"bombs.ShrapnelBomb","sub":"","n":"파편 폭탄","d":"폭발 시 DM-300의 금속 조각들을 사방으로 흩뿌리도록 개조된 폭탄입니다. 폭탄이 폭발하면 폭탄 주변의 굉장히 넓은 범위에 있는 모든 대상에게 _%1$d-%2$d_를 입힙니다. 폭탄이 터지기 전에 반드시 장애물 뒤에 숨어 있어야 할 것입니다...","img":"SHRAPNEL_BOMB"},{"p":"bombs.Bomb","sub":"","n":"폭탄","d":"검은 화약이 꽤 많이 든 폭탄입니다. 폭탄이 폭발하면 근처에 있는 모든 대상에게 _%1$d-%2$d_의 피해를 입히고, 동시에 근처에 있는 지형과 아이템을 파괴할 것입니다.","img":"BOMB"},{"p":"bombs.Firebomb","sub":"","n":"화염 폭탄","d":"폭발이 더 넓게 퍼지도록 개조된 폭탄입니다. 폭탄이 폭발하면 주변 2타일 내에 있는 모든 대상에게 _%1$d-%2$d_의 피해를 입히고, 동시에 범위 내의 모든 지역을 화염으로 뒤덮을 것입니다.","img":"FIRE_BOMB"}],"journal":[{"p":"journal.RegionLorePage","sub":"","n":"RegionLorePage","d":"","img":"SEWER_PAGE"},{"p":"journal.Guidebook","sub":"","n":"던전 숙련 지침서","d":"이것은 모험가를 위한 가이드북으로, 모험을 포기한 누군가가 두고 간 것 같습니다! 특이한 마법이 깃들어 있어, 모험가에게 적절한 순간에 적절한 페이지를 읽도록 유도합니다.\\n\\n유용함도 유용함이지만, 표지에 큼직하게 적힌 \"당황하지 마라!\"라는 커다란 안내 문구 덕에 인기가 많습니다.","img":"MASTERY"},{"p":"journal.GuidePage","sub":"","n":"찢긴 가이드북 쪽지","d":"모험가의 가이드에서 뜯겨져 나온 페이지입니다.\\n\\n대부분의 글자는 멀리서 알아볼 순 없지만, 해당 페이지의 제목은 겨우 읽을 수 있을 정도입니다.\\n\\n_\"%s\"_ 라고 쓰여 있습니다.","img":"GUIDE_PAGE"},{"p":"journal.AlchemyPage","sub":"","n":"찢어진 연금술서 페이지","d":"연금술과 관련된 도서에서 찢겨 나온 페이지입니다.\\n\\n글자가 거리를 두고서는 도저히 읽을 수 없을 정도로 작게 쓰여져 있으며, 제목만 겨우 읽을 수 있을 정도입니다.\\n\\n제목은 _\"%s\"_ 라고 쓰여 있습니다.","img":"ALCH_PAGE"}],"quest":[{"p":"quest.Pickaxe","sub":"","n":"곡괭이","d":"돌을 깨부수는 데 특화된, 무겁지만 튼튼한 도구입니다. 무언가를 채굴하기 위해서라면 딱히 이것을 착용할 필요는 없지만, 절실한 상황에서 사용하기에 적절한 무기 정도는 될 것 같습니다.","img":"PICKAXE"},{"p":"quest.GooBlob","sub":"","n":"구의 점액","d":"구가 죽을 때 떨어져 나온 점액 조각입니다. 커다란 젤리 방울처럼 생겼지만, 먹을 수 있을 것 같지는 않습니다.\\n\\n점액 그  자체로는 효과가 없지만, 특정한 물약 또는 폭탄에 섞을 때 유용하게 쓰일 수 있을 것 같습니다. 적어도 적당한 양의 에너지로 바꾸는 데 사용할 수 있을 것입니다.","img":"BLOB"},{"p":"quest.DwarfToken","sub":"","n":"드워프 주화","d":"많은 드워프들과 그들이 만든 커다란 피조물들은 알 수 없는 이유로 이 작은 금속 조각을 들고 다닙니다. 아마도 보석의 일종이거나 신원 확인용으로 사용한 것으로 보입니다. 좀 수상한 종족이네요.","img":"TOKEN"},{"p":"quest.CorpseDust","sub":"","n":"시체 먼지","d":"이 시체 먼지 덩어리는 다른 먼지 덩어리랑 별 차이 없어 보입니다. 하지만 당신은 사악한 에너지가 이것을 감싸고 있는 것을 느낍니다.\\n\\n가능한 한 빨리 없애 버리는게 좋을 것입니다.","img":"DUST"},{"p":"quest.DarkGold","sub":"","n":"어두운 금 원석","d":"이 금속이 이러한 이름이 붙은 이유는 사실 평범한 금과 별로 달라 보이지 않지만, 태양빛 아래에 두면 녹아버려 쓸모가 없어져 버리기 때문입니다.","img":"ORE"},{"p":"quest.CeremonialCandle","sub":"","n":"의식용 양초","d":"녹여져 한 덩어리로 굳어 버린 양초 더미입니다.\\n\\n각각의 양초는 쓸모가 없지만, 다른 양초와 함께 특정한 모양으로 설치하면 소환 의식에 사용할 힘을 모을 수 있습니다.","img":"CANDLE"},{"p":"quest.MetalShard","sub":"","n":"저주받은 쇳조각","d":"DM-300이 파괴될 때 그것으로부터 떨어져 나온 녹슨 저주받은 금속 조각입니다. 당신은 그것으로부터 비활성화된 악의적인 마법을 느낄 수 있습니다.\\n\\n쇳조각은 그 자체로는 아무런 효과는 없지만, 특정한 주문서 또는 폭탄에 섞을 때 유용하게 쓰일 수 있을 것 같습니다. 적어도 적당한 양의 에너지로 바꾸는 데 사용할 수 있을 것입니다.","img":"SHARD"},{"p":"quest.Embers","sub":"","n":"정령의 잉걸불","d":"이 특이한 잉걸불은 어린 불정령에서만 채취할 수 있습니다. 뜨거운 에너지를 발산하고 있습니다.","img":"EMBER"}],"scroll":[{"p":"scrolls.ScrollOfIdentify","sub":"","n":"감정의 주문서","d":"이 주문서는 하나의 아이템의 비밀을 영구적으로 드러냅니다.","img":"SCROLL_HOLDER"},{"p":"scrolls.ScrollOfUpgrade","sub":"","n":"강화의 주문서","d":"이 주문서는 아이템 하나 혹은 투척 무기 한 세트를 강화합니다. 마법 막대의 위력과 충전량이 증가하고, 무기와 방어구의 피해량과 방어력이 증가하며, 투척 무기는 완전히 수리됨과 동시에 더 오래 쓸 수 있게 되고, 반지의 효과는 더욱 강력해집니다.\\n\\n강화는 저주 해제의 주문서만큼 강력하지는 않지만, 저주를 약화하거나 때로는 완전히 해제할 수도 있습니다. 안타깝게도 강화 마법은 높은 강화 수치를 가진 장비에 부여된 마법이나 상형문자도 지울 수 있습니다.","img":"SCROLL_HOLDER"},{"p":"scrolls.ScrollOfMirrorImage","sub":"","n":"거울상의 주문서","d":"이 주문서에 적힌 주문은 사용자의 분신을 두 개 소환합니다. 분신들은 원본처럼 적들을 쫓아다닐 것입니다. 하지만 내구력이 약해 피해를 입으면 즉시 사라질 것입니다.","img":"SCROLL_HOLDER"},{"p":"scrolls.ScrollOfTeleportation","sub":"","n":"공간이동의 주문서","d":"이 양피지에 적힌 마법은 즉시 독자를 현재 층의 다른 위치로 이동시킵니다. 이 주문서는 독자가 이전에 가보지 못한 장소를 우선하나, 잠긴 문이나 바리케이드를 통과하지 못합니다. 다만, 새로운 곳으로 향하는 숨겨진 문을 드러낼 수는 있습니다.","img":"SCROLL_HOLDER"},{"p":"scrolls.ScrollOfTerror","sub":"","n":"공포의 주문서","d":"이 주문서를 사용하면 주문서로부터 방출되는 시뻘건 빛이 사용자의 시야 안에 있는 적들을 공포로 압도하여, 그들을 도망치게 할 것입니다. 도망치는 적들을 공격하면 공포 효과의 지속 시간이 줄어들게 됩니다.","img":"SCROLL_HOLDER"},{"p":"scrolls.ScrollOfMagicMapping","sub":"","n":"마법 지도의 주문서","d":"이 주문서를 읽으면, 수정같이 맑은 형상이 기억에 각인되어, 현재 층의 모든 비밀을 포함한 지형을 드러나게 합니다. 아이템과 생물체들의 위치는 여전히 알 수 없습니다.","img":"SCROLL_HOLDER"},{"p":"scrolls.ScrollOfTransmutation","sub":"","n":"변환의 주문서","d":"이 주문서는 강력한 변환 마법이 담겨있습니다. 특정한 아이템에 사용하면 같은 종류의 아이템 중 하나로 바꾸어 버립니다. 변환된 아이템의 강화 수치, 마법 상형문자는 보존됩니다. 마법 주문서나 물약에 사용할 시 신비로운 주문서 또는 물약이 나오며, 이미 변환된 아이템은 변환되기 전으로 돌아갑니다.","img":"SCROLL_HOLDER"},{"p":"scrolls.ScrollOfRage","sub":"","n":"분노의 주문서","d":"이 주문서를 읽으면, 모든 적들을 독자에게로 이끌게 되며, 가까운 적들을 격분시키는 엄청난 함성을 발사합니다.","img":"SCROLL_HOLDER"},{"p":"scrolls.ScrollOfLullaby","sub":"","n":"자장가의 주문서","d":"이 주문서를 읽으면 부드러운 선율이 흘러나와 그것을 듣는 모두를 깊은 마법의 잠에 빠지게 합니다. 독자와 그 아군에 대해서는 잠에 회복 효과가 있습니다.","img":"SCROLL_HOLDER"},{"p":"scrolls.ScrollOfRemoveCurse","sub":"","n":"저주 해제의 주문서","d":"이 주문서에 담긴 마법은 사용자의 무기, 반지, 마법봉, 유물에 깃든 저주를 즉시 제거합니다.","img":"SCROLL_HOLDER"},{"p":"scrolls.ScrollOfRetribution","sub":"","n":"징벌의 주문서","d":"이 주문서는 사용자의 고통을 힘의 폭발로 바꾸어 줍니다. 사용자가 피해를 많이 입은 상태일수록 파괴력이 강해지며, 빈사 상태일 때 사용하면 거의 모든 적들을 죽일 수 있습니다.\\n\\n이 주문서를 읽으면 잠시 동안 눈이 멀고 약화됩니다.","img":"SCROLL_HOLDER"},{"p":"scrolls.ScrollOfRecharging","sub":"","n":"충전의 주문서","d":"이 주문서에 담겨 있는 그대로의 마력은 풀려날 때 사용자의 모든 마법 막대를 천천히 충전시킵니다.","img":"SCROLL_HOLDER"},{"p":"scrolls.exotic.ScrollOfChallenge","sub":"exotic","n":"도전의 주문서","d":"크게 소리쳐 읽었을 때, 이 주문서는 포효하여 적의 주의를 끌고 그와 동시에 독자 중심의 작은 투기장을 만들어 냅니다.\\n\\n독자가 투기장 안에 있는 동안 (다른 피해 경감 효과보다 먼저 적용되는)33%의 피해 경감 효과를 얻으며 허기를 느끼지 않습니다.\\n\\n투기장의 크기는 독자가 있는 공간의 크기에 비례합니다. 보스가 있는 층에서는 투기장이 굉장히 작아집니다.","img":"SCROLL_HOLDER"},{"p":"scrolls.exotic.ScrollOfDread","sub":"exotic","n":"두려움의 주문서","d":"이 주문서를 읽으면 주문서가 시뻘겋게 빛나며 당신의 시야 안에 있는 모든 적에게 엄청난 공포를 심어 줄 것입니다. 적들은 이 효과가 너무 큰 나머지 던전에서 도망치려 할 것이며, 다시는 보이지 않게 될 것입니다!\\n\\n공포 효과와 비슷하게, 시간이 지나거나 공격을 받으면 두려움에서 벗어날 수 있습니다.\\n\\n보스와 같은 강력한 정신력을 가진 적들은 대신 일반 공포 효과를 받게 될 것입니다.","img":"SCROLL_HOLDER"},{"p":"scrolls.exotic.ScrollOfEnchantment","sub":"exotic","n":"마법 부여의 주문서","d":"이 주문서는 무기나 갑옷에 강력한 마법 에너지를 융합합니다. 또한 시전자가 부여할 마법을 어느정도 결정할 수도 있습니다.","img":"SCROLL_HOLDER"},{"p":"scrolls.exotic.ScrollOfSirensSong","sub":"exotic","n":"사이렌의 노래의 주문서","d":"이 주문서를 읽으면 적 하나를 홀려 아군으로 만들어 버리는 매혹적인 선율이 흘러나옵니다! 이 멜로디를 들은 다른 적들은 잠시 동안 매혹될 것입니다.\\n\\n특출나게 강력한 적들은 이러한 매료 효과에 저항할 것이며, 대신 매혹될 것입니다.","img":"SCROLL_HOLDER"},{"p":"scrolls.exotic.ScrollOfMysticalEnergy","sub":"exotic","n":"신비한 에너지의 주문서","d":"이 주문서에 담겨 있는 그대로의 마력은 풀려날 때 사용자의 유물을 서서히 충전시킵니다.","img":"SCROLL_HOLDER"},{"p":"scrolls.exotic.ScrollOfForesight","sub":"exotic","n":"예지의 주문서","d":"이 주문서를 읽고 나면 주변 지형지물의 정보가 수정처럼 명확하게  독자의 머릿속에 지속적으로 제공됩니다. 이 효과는 꽤나 오랜 시간 동안 지속되며, 또한 모든 숨겨진 문이나 함정을 밝혀 내기 때문에 탐색이 필요 없게 됩니다.","img":"SCROLL_HOLDER"},{"p":"scrolls.exotic.ScrollOfDivination","sub":"exotic","n":"점성술의 주문서","d":"이 주문서는 당신이 현재 알고 있지 않은 네 가지 아이템을 무작위로 식별합니다. 물약의 색깔이나, 주문서의 룬 문자나, 반지에 박힌 보석이 감정될 수 있으며, 당신이 가지고 있지 않은 아이템도 감정될 수 있습니다.","img":"SCROLL_HOLDER"},{"p":"scrolls.exotic.ScrollOfPsionicBlast","sub":"exotic","n":"정신 폭발의 주문서","d":"이 주문서에는 시야 내에 들어온 모든 대상의 정신을 찢어버릴 수 있는 파괴의 에너지가 들어 있습니다.\\n\\n이 주문서에서 나온 힘은 독자를 일시적으로 눈이 멀게 만들고, 기절시키며, 상당한 피해를 입힙니다. 피해를 입은 대상이 많을수록 자가 피해가 적어집니다.","img":"SCROLL_HOLDER"},{"p":"scrolls.exotic.ScrollOfMetamorphosis","sub":"exotic","n":"탈바꿈의 주문서","d":"이 주문서는 아이템이 아닌 시전자에게 적용되는 강력한 변환 마법을 담고 있습니다. 이 주문서의 마법은 당신이 고른 특성 하나를 다른 직업의 동일 특성 티어에 있는 종류의 다섯 특성 중 하나로 바꿀 수 있게 해 줍니다!\\n\\n이 효과는 직업 특성을 바꾸는 데에만 사용할 수 있으며, 보조 직업 특성이나 갑옷 특성은 바꿀 수 없습니다. 또한 당신이 사용할 수 없는 특성은 제공되지 않습니다.","img":"SCROLL_HOLDER"},{"p":"scrolls.exotic.ScrollOfPassage","sub":"exotic","n":"통로의 주문서","d":"이 주문서는 사용자를 해당 지역의 첫번째 층 입구로 순간이동시킵니다. 상점으로 빠르게 이동하는 데 안성맞춤입니다.","img":"SCROLL_HOLDER"},{"p":"scrolls.exotic.ScrollOfPrismaticImage","sub":"exotic","n":"프리즈마 거울상의 주문서","d":"이 주문서에는 사용자를 닮은 다채로운 환영을 소환하는 마법이 담겨 있습니다. 프리즈마 거울상은 사용자와 비슷한 방어력, 그리고 낮은 체력과 공격력을 가지고 사용자의 약한 분신처럼 행동합니다.\\n\\n프리즈마 거울상은 적이 나타날 경우 스스로를 드러내, 사용자를 지키려 할 것입니다.\\n\\n만약 프리즈마 거울상이 이미 존재한다면, 이 주문서는 그것의 체력을 완전히 회복시킬 것입니다.","img":"SCROLL_HOLDER"},{"p":"scrolls.exotic.ScrollOfAntiMagic","sub":"exotic","n":"항마의 주문서","d":"이 주문서의 마법은 당신을 마법 오라로 둘러싸 잠시 동안 이롭거나 해로운 마법 효과 모두를 차단합니다. 마법 막대, 주문서, 반지, 유물, 무기 마법, 그리고 저주의 효과 발생을 막습니다. 하지만 영웅의 갑옷 능력은 이 효과를 무시할 정도로 강력하기 때문에, 여전히 사용이 가능합니다.","img":"SCROLL_HOLDER"}],"stone":[{"p":"stones.StoneOfAggression","sub":"","n":"공격성의 돌","d":"이 돌을 아군이나 적군에게 던지면 짧은 시간동안 주변의 모든 적들이 대상 캐릭터를 공격할 확률이 증가합니다\\n\\n\\n그러나 보스들은 이 효과에 저항할 수 있으며, 그들이 소환한 하수인으로부터의 피해를 경감하고 지속 시간 또한 크게 줄일 것입니다.","img":"STONE_AGGRESSION"},{"p":"stones.StoneOfDeepSleep","sub":"","n":"깊은 수면의 돌","d":"적에게 이 돌을 던지면, 대상은 깊은 마법의 수면에 빠지게 되어 방해받기 전까지 영원히 잠을 자게 됩니다.","img":"STONE_SLEEP"},{"p":"stones.StoneOfFear","sub":"","n":"두려움의 돌","d":"다른 캐릭터에게 이 돌을 던지면, 그 대상은 공포로 압도되어 뒤돌아서 도망치려 할 것입니다. 도망치는 적을 공격하면 공포의 지속시간이 줄어듭니다.","img":"STONE_FEAR"},{"p":"stones.StoneOfEnchantment","sub":"","n":"마법 부여의 돌","d":"이 룬석은 마법 부여의 힘이 담겨 있습니다. 강화의 주문서처럼 장비 자체의 질을 향상시키지는 않지만, 대신 무기와 방어구와 융합하여 장비에 마법을 부여할 수 있습니다.","img":"STONE_ENCHANT"},{"p":"stones.StoneOfDetectMagic","sub":"","n":"마법 탐지의 돌","d":"이 룬석은 아이템에 부여된 마법을 탐지할 수 있습니다. 이 돌을 감정하지 않은 아이템에 사용하면 해당 아이템에 악의 담긴 마법이 부여되어 있는지, 혹은 강화나 인챈트와 같은 긍정적인 마법이 부여되어 있는지 확인할 수 있습니다.","img":"STONE_DETECT"},{"p":"stones.StoneOfFlock","sub":"","n":"양떼의 돌","d":"이 돌은 던져진 지점 주변에 마법의 양을 소환합니다.","img":"STONE_FLOCK"},{"p":"stones.StoneOfBlink","sub":"","n":"점멸의 돌","d":"이 돌은 던져진 지점으로 사용자를 즉시 순간이동 시킵니다.","img":"STONE_BLINK"},{"p":"stones.StoneOfAugmentation","sub":"","n":"증강의 돌","d":"이 룬석은 장비를 증강시켜 한 특성을 강화시키지만 다른 특성을 약화시킵니다.\\n\\n무기에 사용하여 속도와 공격력 중 하나를 강화할 수 있습니다. 또한 투척 무기의 경우 공격 속도에 비례해서 내구도를 얻거나 잃게 됩니다.\\n\\n갑옷에 사용하여 회피와 방어력 중 하나를 강화할 수 있습니다.","img":"STONE_AUGMENTATION"},{"p":"stones.StoneOfIntuition","sub":"","n":"직감의 돌","d":"이 룬석은 감정의 마법서와 같은 종류의 약한 마법을 품고 있습니다. 직접 아이템을 감정할 수는 없으나, 당신의 직감과 결합하여 지정한 물약이나 주문서, 혹은 반지의 종류를 추측해낼 수 있습니다.","img":"STONE_INTUITION"},{"p":"stones.StoneOfClairvoyance","sub":"","n":"청명의 돌","d":"이 돌은 던져진 곳을 중심으로 매우 넓은 구역에 있는 모든 숨겨진 타일들을 드러냅니다. 이 효과는 심지어 벽 너머로도 적용됩니다.","img":"STONE_CLAIRVOYANCE"},{"p":"stones.StoneOfShock","sub":"","n":"충격의 돌","d":"이 돌은 던져진 지점에 짧은 시간 동안 번개 폭풍을 생성하여 주변의 적들을 마비시키고, 맞은 적의 수만큼 사용자의 마법 막대를 충전시킵니다.","img":"STONE_SHOCK"},{"p":"stones.StoneOfBlast","sub":"","n":"폭발의 돌","d":"이 돌은 던져진 지점에 즉시 폭발을 일으킵니다. 일반 폭탄처럼 주변의 모든 대상에게 피해를 줍니다.","img":"STONE_BLAST"},{"p":"stones.StoneOfDisarming","sub":"","n":"해체의 돌","d":"이 룬석은 던전에 숨겨진 사악한 함정들을 무력화시킬 수 있는 마법이 담겨있습니다. 던져진 곳 주변의 함정을 최대 9개까지 무력화시킬 것입니다.","img":"STONE_DETECT"}],"weapon":[{"p":"weapon.missiles.darts.ChillingDart","sub":"dart","n":"냉동 다트","d":"이 다트의 끝부분은 눈꽃송이 추출물이 발려 있어 맞은 적을 잠시 동안 냉동시킵니다.","img":"CHILLING_DART"},{"p":"weapon.missiles.darts.PoisonDart","sub":"dart","n":"독 다트","d":"이 다트의 끝부분은 슬픔이끼 추출물이 발려 있어 맞은 적을 중독시킵니다.","img":"POISON_DART"},{"p":"weapon.missiles.darts.ParalyticDart","sub":"dart","n":"마비 다트","d":"이 다트의 끝부분은 뱀뿌리 추출물이 발려 있어 맞은 적을 잠시 동안 기절시킵니다.","img":"PARALYTIC_DART"},{"p":"weapon.missiles.darts.DisplacingDart","sub":"dart","n":"변위 다트","d":"이 다트의 끝부분은 미명초 추출물이 발려 있어 맞은 적을 짧은 거리로 순간이동시킵니다.","img":"DISPLACING_DART"},{"p":"weapon.missiles.darts.RotDart","sub":"dart","n":"부패 다트","d":"사악한 다트 끝에는 다트를 맞은 어떤 것이든 공격적으로 먹어치우는 썩은열매 기반의 산성 물질 혼합물이 발라져 있습니다. 강력한 적들은 효과의 대분에 저항을 가지지만, 부식은 대부분의 일반적인 적들을 손쉽게 죽이기에 충분합니다. 이 다트들은 다른 끝을 붙인 다트들보다 기본적으로 더 높은 내구도를 가지지만, 내구도를 더 늘릴 수는 없습니다.","img":"ROT_DART"},{"p":"weapon.missiles.darts.HolyDart","sub":"dart","n":"신성 다트","d":"이 다트는 대상에게 신성한 에너지를 주입하는 별꽃 추출물이 발려 있습니다. 아군과 일반적인 적은 축복받으며, 언데드와 악마 적들은 큰 피해를 입습니다. 다트 자체의 피해는 적에게만 적용됩니다.","img":"HOLY_DART"},{"p":"weapon.missiles.darts.BlindingDart","sub":"dart","n":"실명 다트","d":"이 다트의 끝부분은 실명초 추출물이 발려 있어 맞은 적을 잠시 동안 실명시킵니다. 하지만 적의 방향 감각을 상실시키지 않아서 여전히 당신이 있던 곳을 기억할 것입니다.","img":"BLINDING_DART"},{"p":"weapon.missiles.darts.AdrenalineDart","sub":"dart","n":"아드레날린 다트","d":"이 다트는 신속엉겅퀴 추출물이 발려 있으며, 대상 아군의 이동과 공격 속도를 대폭 늘리거나, 대상 적의 속도를 잠시 늦춥니다. 다트 자체의 피해는 적에게만 적용됩니다.","img":"ADRENALINE_DART"},{"p":"weapon.missiles.darts.IncendiaryDart","sub":"dart","n":"인화성 다트","d":"이 다트의 끝부분은 화염초 추출물이 발려 있어 충격을 주면 밝은 빛으로 타오릅니다.","img":"INCENDIARY_DART"},{"p":"weapon.missiles.darts.ShockingDart","sub":"dart","n":"전격 다트","d":"이 다트의 끝부분은 폭풍덩굴 추출물이 발려 있어 맞은 적에게 전기 충격을 발생시킵니다.","img":"SHOCKING_DART"},{"p":"weapon.missiles.darts.CleansingDart","sub":"dart","n":"정화 다트","d":"이 다트는 아군이 해로운 효과에 면역이 되게 하거나, 적이 가진 이로운 효과를 제거하는 마법풀 추출물이 발려 있습니다. 또한 맞은 적의 주의를 돌리거나 도망치게 만들 수도 있습니다. 다트 자체의 피해는 적에게만 적용됩니다.","img":"CLEANSING_DART"},{"p":"weapon.missiles.darts.HealingDart","sub":"dart","n":"치유 다트","d":"이 다트는 대상을 급속도로 치유할 수 있는 태양초 추출물이 발려 있습니다. 다트 그 자체는 여전히 적들을 해치지만, 동료들은 해치지 않을 것입니다.","img":"HEALING_DART"},{"p":"weapon.missiles.darts.Dart","sub":"dart","n":"다트","d":"끝부분에 금속 가시가 달린 나무 막대로써 손목의 튕김으로 쉽게 날려보내  적들에게 꽂을 수 있도록 만들어졌습니다. 여기에 씨앗 추출물을 발라 던질 때 추가 효과를 얻을 수 있습니다.","img":"DART","t":1},{"p":"weapon.melee.MagicalArtifact","sub":"melee","n":"MagicalArtifact","d":"","img":"SINGEL","mod2":true},{"p":"weapon.melee.Cudgel","sub":"melee","n":"곤봉","d":"소형 황동 메이스입니다. 본격적인 여행용 무기보다는 귀족들의 호신용 물품에 가깝습니다.","img":"CUDGEL","t":1},{"p":"weapon.melee.WornShortsword","sub":"melee","n":"낡은 소검","d":"오래 사용하여 낡아버린 소검입니다. 보통 소검보다 가볍고 피해를 덜 입힙니다.","img":"WORN_SHORTSWORD","t":1},{"p":"weapon.melee.Dagger","sub":"melee","n":"단검","d":"적당히 닳은 나무 손잡이가 있는 간단한 무쇠 단검입니다.","img":"DAGGER","t":1},{"p":"weapon.melee.Rapier","sub":"melee","n":"레이피어","d":"이 곧은 세검은 베는 위력을 희생한 대가로 약간의 방어 능력을 가지고 있습니다.","img":"RAPIER","t":1},{"p":"weapon.melee.MagesStaff","sub":"melee","n":"마법사의 지팡이","d":"마법사가 스스로 만든 지팡이는 다른 마법 막대를 융합할 수 있는 독특한 마법 무기입니다.","img":"MAGES_STAFF","t":1},{"p":"weapon.melee.Gloves","sub":"melee","n":"징 박힌 장갑","d":"이 징 박힌 장갑은 실질적인 보호를 제공하지는 않지만, 손을 자유롭게 유지하면서 튼튼한 무기로 활용할 수 있습니다.","img":"GLOVES","t":1},{"p":"weapon.melee.Dirk","sub":"melee","n":"더크","d":"더 기다란 찌르기용 단검으로, 칼날을 적에게 더 깊숙이 박아 넣을 수 있도록 되어 있습니다.","img":"DIRK","t":2},{"p":"weapon.melee.Shortsword","sub":"melee","n":"소검","d":"이 무기는 단검보다 겨우 한두 뼘 정도 긴 무기에 불과합니다.","img":"SHORTSWORD","t":2},{"p":"weapon.melee.Sickle","sub":"melee","n":"손낫","d":"한 손으로 사용하는 농사 기구로, 다루기 까다롭지만 강력한 무기도 될 수 있습니다.","img":"SICKLE","t":2},{"p":"weapon.melee.HandAxe","sub":"melee","n":"손도끼","d":"가벼운 도끼로써, 보통은 나무를 벨 때 사용합니다. 적을 벨 때도 적당한 날을 가졌습니다.","img":"HAND_AXE","t":2},{"p":"weapon.melee.Quarterstaff","sub":"melee","n":"육척봉","d":"단단한 나무로 만들어진 지팡이이며, 끝 부분에 금속으로 된 테로 둘러져 있습니다.","img":"QUARTERSTAFF","t":2},{"p":"weapon.melee.Spear","sub":"melee","n":"창","d":"길쭉한 나무봉 끝에 날카로운 쇠가 붙어있습니다.","img":"SPEAR","t":2},{"p":"weapon.melee.Sword","sub":"melee","n":"검","d":"괜찮게 균형잡힌 검입니다. 너무 크지는 않지만, 확실히 소검보다는 큽니다.","img":"SWORD","t":3},{"p":"weapon.melee.Mace","sub":"melee","n":"메이스","d":"이 무기 끝에 달린 철구는 적에게 적당한 뇌진탕을 안겨줍니다.","img":"MACE","t":3},{"p":"weapon.melee.Scimitar","sub":"melee","n":"시미타","d":"두꺼운 곡검입니다. 이 검은 빠르지만 그만큼 피해를 덜 입힙니다.","img":"SCIMITAR","t":3},{"p":"weapon.melee.Sai","sub":"melee","n":"쌍차도","d":"양 손에 하나씩 들 수 있는 두개의 얇은 검입니다. 빠르게 상처를 입혀 적을 쓰러뜨리기에 좋습니다.","img":"SAI","t":3},{"p":"weapon.melee.RoundShield","sub":"melee","n":"원형 방패","d":"이 커다란 방패는 공격을 효과적으로 방어하며, 위기에 몰렸을 때에는 그럭저럭 괜찮은 무기도 됩니다.","img":"ROUND_SHIELD","t":3},{"p":"weapon.melee.Whip","sub":"melee","n":"채찍","d":"이 무기의 끝에 달린 기다란 가시줄은 형편없는 피해를 입히지만, 사정거리만큼은 다른 무기와 비교할 수 없습니다.","img":"WHIP","t":3},{"p":"weapon.melee.Katana","sub":"melee","n":"도","d":"커다란 금속제 가드 위로 뻗어나간 가느다란 도신을 지닌 검입니다.","img":"KATANA","t":4},{"p":"weapon.melee.RunicBlade","sub":"melee","n":"룬 검","d":"먼 곳에서 온 정체불명의 무기로, 밝은 푸른빛의 날을 가지고 있습니다.","img":"RUNIC_BLADE","t":4},{"p":"weapon.melee.Crossbow","sub":"melee","n":"쇠뇌","d":"이 복잡한 구조의 무기는 화살을 매우 빠른 속도로 발사할 수 있습니다. 그리 권장되지는 않지만, 쇠뇌의 무겁고 단단한 부분 덕분에 근접 무기로도 그럭저럭 활용할 수 있습니다.","img":"CROSSBOW","t":4},{"p":"weapon.melee.AssassinsBlade","sub":"melee","n":"암살자의 칼","d":"흑요석으로 만들어진 작은 물결모양 칼입니다. 가볍지만 다루기 어려우며, 그만큼 제대로 적중하면 치명적입니다.","img":"ASSASSINS_BLADE","t":4},{"p":"weapon.melee.Longsword","sub":"melee","n":"장검","d":"이 검의 예리하고 날카로운 강철 칼날은 사용자를 안심시킬 정도입니다. 그러나 그 길이로 인해 많이 무겁습니다.","img":"LONGSWORD","t":4},{"p":"weapon.melee.BattleAxe","sub":"melee","n":"전투 도끼","d":"이 전투 도끼의 거대한 강철 도끼날은 매 공격마다 상당한 무게감을 줍니다.","img":"BATTLE_AXE","t":4},{"p":"weapon.melee.Flail","sub":"melee","n":"철퇴","d":"가시 박힌 공이 손잡이에 달린 사슬 끝에 달려 있습니다. 다루기 까다롭지만, 제대로 맞으면 파괴적입니다.","img":"FLAIL","t":4},{"p":"weapon.melee.Glaive","sub":"melee","n":"글레이브","d":"기다란 봉 끝에 달린 칼날로 이루어진 거대한 냉병기입니다.","img":"GLAIVE","t":5},{"p":"weapon.melee.Gauntlet","sub":"melee","n":"돌 건틀릿","d":"이 무거운 건틀릿은 무거운 마법석으로 덮인 붉은색 천으로 만들어졌습니다. 천이 손을 제대로 감싸며 무거운 마법석이 마치 몸의 일부인 것 처럼 느껴집니다. 이 무거운 무기를 휘두르는데는 큰 힘이 필요하지만, 그만큼의 큰 타격을 보장합니다.","img":"GAUNTLETS","t":5},{"p":"weapon.melee.WarScythe","sub":"melee","n":"전쟁 낫","d":"거대하고 다루기 까다로운 이 농기구는 식물보다 적을 더 잘 벨 수 있도록 개조되었습니다.","img":"WAR_SCYTHE","t":5},{"p":"weapon.melee.WarHammer","sub":"melee","n":"전쟁 망치","d":"거대한 납과 강철 덩어리로 만들어진 이 망치의 파괴적인 공격을 막을 수 있는 생물체는 얼마 없습니다. 하지만 효율적으로 다루기 위해선 많은 힘을 필요로 합니다.","img":"WAR_HAMMER","t":5},{"p":"weapon.melee.Greataxe","sub":"melee","n":"특대 도끼","d":"어깨로 받쳐야 겨우 들 수 있는 이 거대한 도끼는, 그 무게에 걸맞는 강력한 파괴력을 가집니다.","img":"GREATAXE","t":5},{"p":"weapon.melee.Greatshield","sub":"melee","n":"특대 방패","d":"방패보단 차라리 움직이는 장벽이란 말이 어울릴 것 같은 이 거대한 쇳덩어리는 방어를 돕지만, 공격 수단으로 쓰기에는 다소 거추장스럽습니다.","img":"GREATSHIELD","t":5},{"p":"weapon.melee.Greatsword","sub":"melee","n":"특대검","d":"이 거대한 칼날은 무게를 주어 휘둘러 적들에게 커다란 피해를 입힙니다.","img":"GREATSWORD","t":5},{"p":"weapon.missiles.ThrowingSpike","sub":"missile","n":"투척용 대못","d":"이 튼튼하고 뾰족한 금속 화살은 멀리 있는 적에게 던지기 위해 만들어졌습니다.","img":"THROWING_SPIKE","t":1},{"p":"weapon.missiles.ThrowingStone","sub":"missile","n":"투척용 돌","d":"이 돌멩이들은 일반적인 돌보다 더 강하게 던질 수 있도록 가공되었습니다.","img":"THROWING_STONE","t":1},{"p":"weapon.missiles.ThrowingKnife","sub":"missile","n":"투척용 칼","d":"이 가벼운 칼들은 바람을 가르며 목표의 목을 가르기에도 적합합니다.","img":"THROWING_KNIFE","t":1},{"p":"weapon.missiles.Shuriken","sub":"missile","n":"수리검","d":"날카로운 칼날이 달린 별 모양의 이 금속 조각은 움직인 후에 재빠르게 던질 수 있습니다.","img":"SHURIKEN","t":2},{"p":"weapon.missiles.FishingSpear","sub":"missile","n":"작살","d":"낚시용으로 설계되었지만, 급조 무기 치고는 쓸만한 작은 투척용 창입니다.","img":"FISHING_SPEAR","t":2},{"p":"weapon.missiles.ThrowingClub","sub":"missile","n":"투척용 몽둥이","d":"매우 단순하지만 내구성이 뛰어난 투척 무기로, 기본적으로 막대기에 큰 돌을 고정한 형태입니다.","img":"THROWING_CLUB","t":2},{"p":"weapon.missiles.Bolas","sub":"missile","n":"올가미","d":"이 특이한 투척 무기는 비교적 약한 피해를 입히지만 대상을 감속시키는 데는 제격입니다.","img":"BOLAS","t":3},{"p":"weapon.missiles.Kunai","sub":"missile","n":"쿠나이","d":"이 조그마한 칼들은 노련한 사용자의 손에 쥐어 주면 매우 강력한 성능을 자랑합니다.","img":"KUNAI","t":3},{"p":"weapon.missiles.ThrowingSpear","sub":"missile","n":"투척용 창","d":"이 가벼운 창들은 얇은 몸체를 가져 직접 찌르기엔 부적합하지만, 던져 날리기엔 적합합니다.","img":"THROWING_SPEAR","t":3},{"p":"weapon.missiles.HeavyBoomerang","sub":"missile","n":"무거운 부메랑","d":"이 커다란 부메랑은 제대로 다루기 어렵지만, 꽤 큰 피해를 줍니다.","img":"BOOMERANG","t":4},{"p":"weapon.missiles.Javelin","sub":"missile","n":"투창","d":"이 기다란 투창의 무게 중심은 가시가 있는 앞 부분에 쏠려 있어 날아가는 동안 힘을 실을 수 있게 됩니다.","img":"JAVELIN","t":4},{"p":"weapon.missiles.Tomahawk","sub":"missile","n":"투척용 도끼","d":"이 톱니 모양의 날이 달린 투척 도끼는 맞은 적을 찢어발깁니다.","img":"TOMAHAWK","t":4},{"p":"weapon.missiles.Trident","sub":"missile","n":"삼지창","d":"거대한 투창으로 끝 부분에 무시무시한 3갈래의 갈퀴가 나 있습니다. 이 투척 무기는 강력하지만, 꽤나 무겁습니다.","img":"TRIDENT","t":5},{"p":"weapon.missiles.ThrowingHammer","sub":"missile","n":"투척용 망치","d":"이 묵직한 망치는 적에게 던지기 위해 만들어졌습니다. 튼튼하고 매끈한 무쇠로 만들어져 내구성이 높습니다.","img":"THROWING_HAMMER","t":5},{"p":"weapon.missiles.ForceCube","sub":"missile","n":"힘의 큐브","d":"이 기이한 형상의 마법 큐브는 손에 들고 있기에 충분할 정도로 작지만, 정말로 무겁습니다.","img":"FORCE_CUBE","t":5},{"p":"weapon.SpiritBow","sub":"ranged","n":"영혼의 활","d":"고대의 마법 나무로 만들어진 활입니다. 이 활의 시위와 각인은 창백한 푸른색으로 빛납니다. 시위가 당겨지면, 이 활은 적에게 발사할 수 있는 마법 화살을 만들어낼 것입니다.","img":"SPIRIT_BOW"}],"bag":[{"p":"bags.MagicalHolster","sub":"","n":"마법 보관집","d":"이 얇은 보관집은 어떤 신비로운 동물의 가죽으로 만들어져 있으며, 거기에 깃든 마법의 힘으로 많은 투척 무기와 마법 막대를 담아둘 수 있습니다.\\n\\n여기에 단순히 손을 뻗기만 해도 당신이 쓰려는 물건을 곧바로 집을 수 있습니다.\\n\\n보관집에 걸린 마법으로 인해, 보관집 안에 있는 마법 막대의 충전 속도가 약간 빨라지며 투척 무기들을 조금 더 오래 사용할 수 있게 됩니다.","img":"HOLSTER"},{"p":"bags.PotionBandolier","sub":"","n":"물약 보관대","d":"이 두꺼운 보관대는 당신의 가슴팍을 가로지르도록 만들어졌습니다. 또한 물약과 가죽 물통, 액체 금속 병들을 보관할 수 있는 작은 물약통이 많이 달려 있습니다.\\n\\n이 물약통은 강화된 유리로 만들어져 있어 냉기에 강할 것입니다.","img":"BANDOLIER"},{"p":"bags.VelvetPouch","sub":"","n":"벨벳 주머니","d":"이 작은 벨벳 주머니에는 씨앗, 룬석, 몇몇 연금술 재료와 같은 작은 물건들을 많이 담아둘 수 있습니다.","img":"POUCH"},{"p":"bags.ScrollHolder","sub":"","n":"주문서 보관함","d":"이 관 형태의 보관함은 천문학자가 쓸 법한 도구와 자료를 보관할 용도로 만들었습니다만, 당신의 주문서를 넣을 수 있습니다. 또한 주문 결정과 신비한 바늘, 신비한 송진들을 훌륭하게 보관할 수 있는 보조 주머니도 달려 있습니다.\\n\\n보관함은 방화 재질로 만들어져 있어, 보관한 주문서는 불에 타지 않습니다.","img":"HOLDER"},{"p":"bags.grimoire.GrimoireAria","sub":"grimoire","n":"아리아의 마도서","d":"아리아의 가문에서 전해져 내려오는 비전으로 만들어진 마도서입니다. 영창을 시전하면, 이 마도서는 적에게 발사할 수 있는 마나 볼을 만들어낼 것입니다.","img":"GRIMOIRE_ARIA","mod2":true}],"food":[{"p":"food.StewedMeat","sub":"","n":"고기 스튜","d":"고기를 끓여 스튜로 만들면서 병균과 기생충 등이 사멸된 것 같습니다. 안심하고 먹으세요!","img":"STEWED"},{"p":"food.MeatPie","sub":"","n":"고기 파이","d":"짭짤하게 간이 밴 고기를 얹은 맛있는 파이입니다. 이 음식은 다른 어떤 것보다도 당신의 배를 많이 채워줄 것입니다.","img":"MEAT_PIE"},{"p":"food.Blandfruit","sub":"","n":"단백과","d":"이건 너무 건조하고 쓸모 없을 것 같습니다. 아마 다른 재료와 섞어 요리하면 더 좋아질 수 있을 것 같습니다.","img":"BLANDFRUIT"},{"p":"food.SupplyRation","sub":"","n":"보급 식량","d":"이 식량은 도적 길드의 일원이 또다른 일원을 위해 던전에 남겨 둔 것입니다. 특히 이동 중에도 먹기 쉽도록 설계되었으며, 또 은밀한 임무에 도움을 줄 것입니다.\\n\\n다른 일반적인 식량만큼 배를 채워 주진 못하지만, 대신 재빠르게 먹을 수 있고 약간의 체력을 즉시 회복시키며 또 도적이 가진 그림자의 망토의 충전량을 회복시켜 줄 것입니다.","img":"SUPPLY_RATION"},{"p":"food.Food","sub":"","n":"비상식량","d":"이 비상식량은 평범해 보입니다. 말린 고기, 비스킷 조금 등이 들어 있습니다.","img":"RATION"},{"p":"food.SmallRation","sub":"","n":"소형 비상식량","d":"이 음식은 평범한 비상 식량에서 양만 줄인 제품입니다.","img":"OVERPRICED"},{"p":"food.MysteryMeat","sub":"","n":"수상한 고기","d":"위험을 감수하고 먹어 보십시오!","img":"MEAT"},{"p":"food.FrozenCarpaccio","sub":"","n":"얼린 생고기","d":"얼린 생고기 조각입니다. 얇게 썰어서 바로 먹을 수 있고 또 맛도 의외로 좋습니다.","img":"CARPACCIO"},{"p":"food.PhantomMeat","sub":"","n":"유령 고기","d":"유령 피라냐에서 잘라낸 크고 반짝이는 반투명 고깃덩어리입니다. 이 고기는 조리가 필요 없으며 허기를 완전히 채우고 여러 가지 방어 능력을 한 번에 제공합니다. 이것을 먹으면 투명화, 나무껍질, 약간의 회복을 제공하고 해로운 효과를 치료합니다.","img":"PHANTOM_MEAT"},{"p":"food.Berry","sub":"","n":"작은 던전 열매","d":"이 작은 열매는 던전의 수풀을 뒤지던 사냥꾼이 발견했습니다. 재빨리 먹을 수 있으며, 약간의 배고픔을 해소해줍니다. 어쩌면 쓸만한 씨앗이 들었을지도 모릅니다.","img":"BERRY"},{"p":"food.ChargrilledMeat","sub":"","n":"직화구이 고기","d":"괜찮게 구워진 고기가 된 것 같다.","img":"STEAK"},{"p":"food.Pasty","sub":"","n":"패스티","d":"속을 소고기와 감자로 채운 진짜배기 콘월 방식 전통 음식입니다. 맛있겠네요!","img":"PASTY"}],"remains":[{"p":"remains.BrokenStaff","sub":"","n":"부러진 지팡이","d":"이 마법사의 지팡이는 이전 주인이 최후를 맞이한 후 반으로 부러졌습니다. 당신은 아직도 이 지팡이 안에 미약하게나마 남아 있는 마력을 느낄 수 있으며, 이걸 사용한다면 가지고 있는 마법 막대를 약간 충전시킬 수 있을 것 같습니다. 다만, 실행에 옮길 경우 이 지팡이는 파괴될 겁니다.","img":"BROKEN_STAFF"},{"p":"remains.BrokenHilt","sub":"","n":"부러진 힐트","d":"이 부러진 칼자루는 이전에 패배했던 결투자의 무기에서 비롯된 물건 같습니다. 당신은 아직도 이 칼자루 안에 미약하게나마 남아 있는 무력을 느낄 수 있으며, 이걸 사용한다면 다음 두 번의 공격 명중 시에 약간의 추가 피해를 더할 수 있을 것 같습니다. 다만, 실행에 옮길 경우 이 칼자루는 파괴될 겁니다.","img":"BROKEN_HILT"},{"p":"remains.SealShard","sub":"","n":"인장 파편","d":"이 작고 붉은 밀랍 조각은 쓰러진 전사의 인장에서 나온 것처럼 보입니다. 당신은 아직도 이 밀랍 조각 안에 미약하게나마 남아 있는 의지력과 집착을 느낄 수 있으며, 이걸 사용한다면 스스로에게 약간의 보호막을 두를 수 있을 것 같습니다. 다만, 실행에 옮길 경우 이 밀랍 조각은 파괴될 겁니다.","img":"SEAL_SHARD"},{"p":"remains.TornPage","sub":"","n":"찢긴 쪽지","d":"이 종이는 성직자의 성서에서 찢겨져 나온 것 같습니다. 아직 약간의 신성력이 남아 있어, 사용하면 약간의 체력을 회복합니다. 하지만 사용 시 찢어진 종이는 파괴됩니다.","img":"TORN_PAGE"},{"p":"remains.CloakScrap","sub":"","n":"천 조각","d":"이 반투명한 옷감 조각은 최근 도적이 두르고 있던 그림자의 망토에서 뜯겨 나온 것 같습니다. 당신은 아직도 이 옷감 안에 미약하게나마 남아 있는 신비로운 에너지를 느낄 수 있으며, 이걸 사용한다면 착용 중인 유물을 약간 충전시킬 수 있을 것 같습니다. 다만, 실행에 옮길 경우 이 옷감 조각은 파괴될 겁니다.","img":"CLOAK_SCRAP"},{"p":"remains.BowFragment","sub":"","n":"활 조각","d":"이 부러진 나무 조각은 이전에 실종되었던 사냥꾼이 지니고 있던 영혼의 활의 일부였을 것입니다. 당신은 아직도 이 조각 안에 미약하게나마 남아 있는 자연의 에너지를 느낄 수 있으며, 이걸 사용한다면 주변에 길게 자란 풀 조금을 만들어낼 수 있을 것 같습니다. 다만, 실행에 옮길 경우 이 조각은 파괴될 겁니다.","img":"BOW_FRAGMENT"}],"wand":[{"p":"wands.WandOfPrismaticLight","sub":"","n":"굴절광의 마법 막대","d":"이 막대는 투명한 수정 덩어리로 만들어져서 마치 기다랗고 매끈한 유리처럼 보입니다. 끝부분에는 형형색색의 빛이 춤추고 있으며, 발사되기를 원하는 것 같습니다.","img":"WAND_PRISMATIC_LIGHT"},{"p":"wands.WandOfLivingEarth","sub":"","n":"대지의 마법 막대","d":"이 마법 막대는 기이한 암석과 그를 감싸며 에너지를 내뿜는 노란 띠로 이루어져 있습니다. 당신이 이 마법 막대를 쥐자 암석이 약간 움직인 것처럼 보입니다. 마치 당신의 손을 느낄 수 있는 것처럼 말이죠.","img":"WAND_LIVING_EARTH"},{"p":"wands.WandOfMagicMissile","sub":"","n":"마탄의 마법 막대","d":"이 평범해 보이는 막대는 순수한 마법 에너지를 발사합니다. 이 막대 자체는 특별한 효과를 가지진 않지만, 다른 막대에 비해 더 많은 충전량을 가지며 강화되었을 때 다른 막대들의 위력을 잠시동안 증가시킬 수 있습니다.","img":"WAND_MAGIC_MISSILE"},{"p":"wands.WandOfLightning","sub":"","n":"번개의 마법 막대","d":"이 막대는 쇳덩어리로 만들어져 생각보다 엄청 무겁습니다. 두 개의 지침이 끝 부분에 함께 휘어져 있으며 전류가 둘 사이에 흐르고 있습니다.","img":"WAND_LIGHTNING"},{"p":"wands.WandOfCorrosion","sub":"","n":"부식의 마법 막대","d":"이 막대는 잿빛 몸체에 끝은 밝은 주황색 보석으로 장식되어 있습니다.","img":"WAND_CORROSION"},{"p":"wands.WandOfDisintegration","sub":"","n":"붕괴의 마법 막대","d":"이 막대는 매끈한 흑요석 덩어리로 만들어졌으며, 진보라색 빛이 옆 부분을 타고 끝부분까지 이어져 있습니다. 파괴적인 에너지를 내뿜으고 있으며 그 에너지가 발사되길 기다리고 있습니다.","img":"WAND_DISINTEGRATION"},{"p":"wands.WandOfFrost","sub":"","n":"서리의 마법 막대","d":"이 막대는 일종의 마법 얼음으로 만들어진 것 같습니다. 둥근 끝 부분으로 갈수록 밝게 빛이 납니다. 잡고 있으면 매우 차갑지만, 손이 얼어버리지는 않습니다.","img":"WAND_FROST"},{"p":"wands.WandOfWarding","sub":"","n":"수호의 마법 막대","d":"이 짧은 금속질의 마법 막대의 끝 부분 위에는 밝은 보라색 보석이 떠 있습니다.","img":"WAND_WARDING"},{"p":"wands.WandOfTransfusion","sub":"","n":"이식의 마법 막대","d":"꽤나 평범하게 생긴 막대로써, 자주색 몸통 끝에 달린 칠흑색 보석이 돋보입니다.","img":"WAND_TRANSFUSION"},{"p":"wands.WandOfRegrowth","sub":"","n":"재성장의 마법 막대","d":"이 막대는 전문적인 솜씨로 조각된 얇은 나무 줄기로 만들어졌습니다. 어린 나무처럼 밝고 생기있는 초록색이 마치 진짜 살아있는 나무 같습니다. \"한 생명이 죽으면 또 다른 생명이 태어나는 법... 그리고 영원한 순환은 언제나 계속될지니!\"","img":"WAND_REGROWTH"},{"p":"wands.WandOfBlastWave","sub":"","n":"충격파의 마법 막대","d":"이 막대는 대리석의 일종으로 만들어졌으며, 금색의 테두리와 끝 부분의 둥글고 검은 보석으로 장식되어 있습니다. 손에 쥐었을때 매우 무겁게 느껴집니다.","img":"WAND_BLAST_WAVE"},{"p":"wands.WandOfCorruption","sub":"","n":"타락의 마법 막대","d":"이 막대는 끝 부분에 달린 해골 모양 장식에서 알 수 있듯이 혼란스럽고 어두운 에너지를 발하고 있습니다.","img":"WAND_CORRUPTION"},{"p":"wands.WandOfFireblast","sub":"","n":"화염 폭발의 마법 막대","d":"이 막대는 붉은 색으로 옻칠한 나뭇가지를 금색 잎으로 대강 말아서 만들었습니다. 끝 부분이 떨리고 있어 강력한 마법을 발사하길 원하는 것 같습니다.","img":"WAND_FIREBOLT"}],"ring":[{"p":"rings.RingOfWealth","sub":"","n":"부유함의 반지","d":"이 반지는 보물을 끌어당기는 자석처럼 작용하며, 적들과 상자에서 더 좋은 아이템이 나올 가능성을 늘려 줍니다. 저주받은 반지는 당신이 전리품을 얻을 확률을 감소시킵니다.","img":"RING_HOLDER"},{"p":"rings.RingOfFuror","sub":"","n":"분노의 반지","d":"이 반지는 착용자에게 내면의 분노를 끌어내어, 더 빠르게 공격할 수 있게 합니다. 저주받은 반지는 착용자의 공격 속도를 감소시킵니다.","img":"RING_HOLDER"},{"p":"rings.RingOfArcana","sub":"","n":"신비의 반지","d":"이 반지는 무기에 부여된 마법과 방어구의 상형문자, 그리고 저주의 마법 속성을 증폭시킵니다! 마법의 발동 확률이 우선적으로 증가하며, 반드시 발동하는 마법은 그 위력이 증가합니다. 저주받은 반지는 반대로 마법과 상형문자, 저주를 약화시킵니다.","img":"RING_HOLDER"},{"p":"rings.RingOfHaste","sub":"","n":"신속의 반지","d":"이 반지는 착용자의 이동에 걸리는 제약을 감소시켜 초인적인 속도로 달릴 수 있게 합니다. 저주받은 반지는 착용자를 더 둔하게 만듭니다.","img":"RING_HOLDER"},{"p":"rings.RingOfForce","sub":"","n":"완력의 반지","d":"이 반지는 착용자의 근접 공격을 강화시킵니다. 이 반지가 주는 완력은 무기를 들때 비교적 덜하지만, 무기를 들지 않고 공격하면 더 강한 피해를 줄 수 있습니다. 저주받은 반지는 착용자의 공격력을 약화시킵니다.","img":"RING_HOLDER"},{"p":"rings.RingOfElements","sub":"","n":"원소의 반지","d":"이 반지는 착용자에게 대부분의 원소 및 마법 효과에 대한 저항을 제공하여, 그러한 효과의 피해와 디버프의 지속 시간을 감소시킵니다. 저주받은 반지는 반대의 효과를 줍니다.","img":"RING_HOLDER"},{"p":"rings.RingOfTenacity","sub":"","n":"인내의 반지","d":"이 반지는 착용자가 받은 치명적인 일격에 저항할 수 있게 합니다. 착용자가 더 많이 다칠수록, 피해에 저항하는 정도도 커집니다. 저주받은 반지는 착용자를 더 쉽게 죽게 만듭니다.","img":"RING_HOLDER"},{"p":"rings.RingOfSharpshooting","sub":"","n":"저격의 반지","d":"이 반지는 착용자의 정확성과 조준을 향상시켜 모든 발사체 무기들을 더 강력하고 오래 사용할 수 있게 합니다. 저주받은 반지는 반대의 효과를 줍니다.","img":"RING_HOLDER"},{"p":"rings.RingOfAccuracy","sub":"","n":"정확성의 반지","d":"이 반지는 착용자의 집중력을 향상시켜, 당신의 공격이 목표를 더 쉽게 노릴 수 있게 합니다. 저주받은 반지는 당신의 공격이 더 잘 빗나가게 만듭니다.","img":"RING_HOLDER"},{"p":"rings.RingOfEnergy","sub":"","n":"충전의 반지","d":"이 반지는 비전력을 발하여 당신이 가진 모든 마법 장비의 충전을 가속합니다. 저주받은 반지는 반대로 충전 속도를 늦춥니다.","img":"RING_HOLDER"},{"p":"rings.RingOfEvasion","sub":"","n":"회피의 반지","d":"이 반지는 착용자의 반사신경을 강화시켜 공격을 더 잘 피하도록 만듭니다. 저주받은 반지는 대신 착용자를 공격에 더 쉽게 노출시킵니다.","img":"RING_HOLDER"},{"p":"rings.RingOfMight","sub":"","n":"힘의 반지","d":"이 반지는 착용자의 물리적 특징을 강화하여, 더 강한 힘과 더 많은 최대 체력을 부여합니다. 저주받은 반지는 착용자의 힘을 약화시킵니다.","img":"RING_HOLDER"}],"trinket":[{"p":"trinkets.WondrousResin","sub":"","n":"놀라운 수지","d":"이 반짝이는 파란색 수지는 저주받은 마법 막대의 마법의 정수를 증류한 것 같습니다. 연금술 냄비의 마법이 이 수지를 어느 정도 안정화시킨 것 같으며, 이제 당신의 마법 막대에도 영향을 미치고 있습니다.","img":"WONDROUS_RESIN"},{"p":"trinkets.TrinketCatalyst","sub":"","n":"마법의 촉매제","d":"이 마법의 금색 가루 뭉치는 던전의 어둠 속에서 희미하게 빛나고 있습니다. 이 촉매제는 연금술 솥에서 소량의 연금술 에너지와 결합하여 특별한 장신구를 만드는 데에 사용할 수 있습니다.\\n\\n장신구는 던전이나 적들에게 약간의 변화를 발생시키는 다양하고 서로 다른 효과를 제공할 것입니다. 장신구는 더 큰 효과를 얻기 위해 강화할수록 더 많은 에너지를 소모하며, 아니면 그냥 떨어뜨려 효과를 없앨 수 있습니다.","img":"TRINKET_CATA"},{"p":"trinkets.ShardOfOblivion","sub":"","n":"망각의 파편","d":"연금술 냄비에서 끓여낸 이후, 이 작은 저주받은 금속 파편은 아무것도... 아닌? 것으로 변했습니다. 빛이 그 주위로 휘어지는 것 같고, 들고 있지 않으면 제자리에서 맴돌고 있습니다. 이 파편은 당신의 무지에서 마법의 힘을 끌어내는 것 같으니 너무 생각하지 않는 게 좋을 것 같네요.","img":"OBLIVION_SHARD"},{"p":"trinkets.MimicTooth","sub":"","n":"미믹 이빨","d":"이 커다랗고 날카로운 이빨은 매우 불행한 미믹에게서 뽑혀져 나온 것일 겁니다. 이빨은 던전의 미믹들에게 영향을 주고 있는 것처럼 보이며, 미믹들이 더 자주 등장하게 함과 동시에 더욱 위험하게 만들고 있습니다.","img":"MIMIC_TOOTH"},{"p":"trinkets.SaltCube","sub":"","n":"소금 큐브","d":"이 커다란 소금 결정은 거의 완벽한 큐브 형태로 깎였으며, 연금술 솥에서 녹는 대신 오히려 그 물의 절반을 흡수했습니다. 소금 큐브는 당신이 먹는 음식의 수분을 마법으로 흡수하여 보존하고 있으며, 이에 따라 당신이 얻는 포만감이 증가한 대신 굶주리지 않을 때의 체력 재생량이 감소했습니다.","img":"SALT_CUBE"},{"p":"trinkets.ExoticCrystals","sub":"","n":"신비로운 수정","d":"이 작은 분홍 결정들은 연금술 에너지 결정과 똑같은 모양을 가지고 있습니다. 연금술 에너지로 직접 사용하는 것은 불가능하지만, 이 결정들은 어떠한 방식으로 당신이 발견하는 물약과 주문서에 영향을 주고 있는 것 같습니다.","img":"EXOTIC_CRYSTALS"},{"p":"trinkets.PetrifiedSeed","sub":"","n":"씨앗 화석","d":"이 씨앗은 느린 지질학적 과정이나 마법에 의해 화석화되었습니다. 이 씨앗은 던전의 식생에 마법으로 영향을 미치며, 때때로 씨앗을 룬석으로 바꾸는 것으로 보입니다.","img":"PETRIFIED_SEED"},{"p":"trinkets.ParchmentScrap","sub":"","n":"양피지 조각","d":"이 작은 양피지 조각은 주문서에서 떨어져 나온 것 같습니다. 양피지 조각은 약간의 마력을 유지하고 있으며, 던전에서 등장하는 무기와 방어구에 영향을 주는 것으로 보입니다.","img":"PARCHMENT_SCRAP"},{"p":"trinkets.ThirteenLeafClover","sub":"","n":"열 세 잎 클로버","d":"연금술 냄비에서 끓이다 보니 이 클로버에 새로운 잎이 무럭무럭 자라났습니다! 이 장신구가 제공하는 것이 행운인지 불운인지 가늠하기 어렵습니다. 어쩌면 이 장신구가 당신의 운을 더 혼란스럽게 만드는 것일까요?","img":"CLOVER"},{"p":"trinkets.EyeOfNewt","sub":"","n":"영원의 눈","d":"이 금빛과 검은 빛이 감도는 영원의 눈은 흔한 재료지만, 강화되어 장신구가 되었습니다. 이 눈은 당신의 시야를 좁게 만드는 대신 사물을 다른 방식으로 볼 수 있게 해 줍니다.","img":"EYE_OF_NEWT"},{"p":"trinkets.MossyClump","sub":"","n":"이끼 덩어리","d":"이 젖은 이끼 덩어리는 당신이 아무리 쥐어짜도 수분을 머금고 있는 것 같습니다. 이 이끼 덩어리는 던전 자체에 귀속되어 있는 것처럼 보이며, 잔디와 물을 더 자주 나타나게 만들 것입니다.","img":"MOSSY_CLUMP"},{"p":"trinkets.FerretTuft","sub":"","n":"족제비 터럭","d":"초록색 리본으로 묶은 부드럽고 흰 족제비의 터럭입니다. 족제비는 민첩함, 장난스러움, 그리고 낮은 집중력으로 알려져 있습니다. 이 장신구에도 그 속성이 남아 있어 주변의 모든 것의 회피를 증가시킵니다.","img":"FERRET_TUFT"},{"p":"trinkets.RatSkull","sub":"","n":"쥐 두개골","d":"이 무시무시한 장신구는 일반적인 쥐의 두개골보다 특출나게 크진 않지만, 그래도 이 던전에서 꽤 보기 힘든 거긴 합니다. 두개골에 담긴 마법의 영향인지, 던전에 서식하는 생명체들이 더 많이 모여 들어 더 자주 마주치게 되는 것 같습니다.","img":"RAT_SKULL"},{"p":"trinkets.DimensionalSundial","sub":"","n":"차원의 해시계","d":"이 작은 휴대용 해시계는 이 던전 깊숙한 곳에서도 어떻게든 그림자를 드리울 수 있습니다. 심지어 당신이 똑바로 들고 있지 않아도 말이죠. 그보다 더 이상한 것은 그림자가 드리우는 위치가 이 세계의 태양과는 전혀 관계가 없는 것처럼 보인다는 점입니다. 그림자가 드리워져 있지 않으면, 해시계는 위험을 계속해서 불러일으킬 것입니다.","img":"SUNDIAL"},{"p":"trinkets.VialOfBlood","sub":"","n":"피의 유리병","d":"이 얇은 유리 병에는 던전 주민의 피가 담겨 있으며, 약병을 회전시키면 천천히 움직입니다. 이것이 당신에게 적용되는 치유 효과를 마법으로 강화하지만, 그 효과를 지연시키는 것 같습니다.","img":"BLOOD_VIAL"},{"p":"trinkets.TrapMechanism","sub":"","n":"함정 작동 장치","d":"이 던전에 있는 낭떠러지 함정 하나의 핵심 부품으로, 바닥에서 매우 조심스럽게 떼어 내어 들고 다닐 수 있게 된 것입니다. 그럼에도 던전 자체에 마력으로 귀속되어 있는 것처럼 보이며, 위험한 지형이 더 자주 등장하지만, 위험한 지형에 대한 친숙도 또한 증가합니다.","img":"TRAP_MECHANISM"},{"p":"trinkets.ChaoticCenser","sub":"","n":"혼돈의 향로","d":"연금술 솥에서 약간의 시간이 지난 후 스스로 향이 타오르며 연기를 피워 내는 향로가 나타났습니다! 이러한 가스는 축적되어 무작위한 주기에 따라 적이 있는 방향으로 분출됩니다. 향로는 모든 종류의 가스를 만들어낼 수 있는 것 같지만, 당신은 향로가 가스를 분출하기 직전에 경고를 받게 됩니다.","img":"CHAOTIC_CENSER"}],"spell":[{"p":"spells.WildEnergy","sub":"","n":"격렬한 에너지","d":"이 주문은 DM-300의 동력이었던 저주받은 에너지의 일부를 담고 있습니다. 이 주문을 시전하면 주문이 당신의 마법 막대와 착용중인 유물을 충전해 주지만, 동시에 임의의 저주받은 마법 막대 효과 또한 발휘할 것입니다. 그러나 저주받은 마법을 발사할 위치 정도는 정할 수 있습니다.","img":"WILD_ENERGY"},{"p":"spells.BeaconOfReturning","sub":"","n":"귀환의 신호기","d":"이 복잡한 주문은 사용자에게 지정 위치로 되돌아갈 수 있는 능력을 부여합니다. 이 주문은 오직 돌아올 때만 소비되며, 신호기는 오직 가장 최근에 설정한 위치만을 기억할 것입니다.","img":"RETURN_BEACON"},{"p":"spells.MagicalInfusion","sub":"","n":"마법 융합","d":"이 주문은 강화의 주문서와 동일한 마법 에너지가 깃들어 있지만, 더 안정된 형태를 띠고 있습니다.\\n\\n기본적으로 아이템을 강화할 뿐 아니라, 마법, 상형문자, 저주를 제거하지 않습니다.","img":"MAGIC_INFUSE"},{"p":"spells.UnstableSpell","sub":"","n":"불안정한 주문","d":"이 작고 검은 입방체는 각 면마다 변화하는 룬 형상을 가지고 있습니다.\\n\\n이 주문을 시전하면 무작위 주문서의 효과를 발동시킬 것입니다. 주문서의 효과는 시야 내에 적이 있다면 항상 전투와 관련된 효과가 발동하며, 그렇지 않을 경우 전투와 관련되지 않은 효과가 발동할 것입니다.","img":"UNSTABLE_SPELL"},{"p":"spells.Alchemize","sub":"","n":"연금화","d":"이 주문은 연금술 솥에서 볼 수 있는 것과 유사한 변형의 힘을 가지고 있습니다. 주문을 사용할 때마다 사용자는 하나의 아이템(혹은 같은 아이템 여러 개)를 골드나 연금술 에너지로 바꿀 수 있게 됩니다. 심지어 물약이나 주문서를 연금술 에너지로 바꾸게 되면 감정도 됩니다!\\n\\n연금화 주문은 상점에서 조금씩 팔고 있으며, 연금술 솥에서 씨앗과 룬석, 그리고 약간의 연금술 에너지를 섞어 많은 양을 만들어 낼 수 있습니다.","img":"ALCHEMIZE"},{"p":"spells.TelekineticGrab","sub":"","n":"원격 조종 집게","d":"이 주문은 시전자가 해당 지점에 놓인 모든 아이템 혹은 적에게 박혀 있는 투척 무기를 집을 수 있게 해 줍니다!\\n\\n다른 대상이 소유하고 있는 물건이나 상자 같은 보관함은 집을 수 없습니다.","img":"TELE_GRAB"},{"p":"spells.PhaseShift","sub":"","n":"위상 변화","d":"이 혼돈 주문은 대상 캐릭터를 현재 층의 임의의 위치로 공간이동시키며, 대상을 긴 시간 동안 기절시킵니다. 강력한 적들은 이러한 기절 효과에 저항할 것입니다. 이 주문은 대상 또는 사용자 자신에게 시전할 수 있습니다.","img":"PHASE_SHIFT"},{"p":"spells.Recycle","sub":"","n":"재활용","d":"이 주문은 약한 변형 마법을 담고 있습니다. 장비를 바꿀 수는 없지만, 이 주문은 주문서, 물약, 씨앗, 룬석, 혹은 끝을 붙인 다트를 같은 유형의 무작위 아이템으로 변환할 것입니다.","img":"RECYCLE"},{"p":"spells.CurseInfusion","sub":"","n":"저주 융합","d":"이 주문은 장비 하나에 DM-300 내부에 존재하던 강력한 악성 마법을 주입합니다. 이 주문을 사용한 아이템은 즉시 저주받으며, 마법이나 상형문자가 있었다면 덮어씌워질 것입니다.\\n\\n무기, 방어구, 마법 막대에 사용한 경우, 그 아이템은 저주받음과 동시에 강화 수치를 얻습니다. 이 주문으로 얻는 강화 수치는 중첩되지 않으며, 저주가 사라지면 강화 효과 역시 사라질 것입니다.\\n\\n저주 융합은 여러 번 사용할 수 있으며, 무기나 방어구에 부여된 저주를 바꾸어 줄 것입니다.","img":"CURSE_INFUSE"},{"p":"spells.SummonElemental","sub":"","n":"정령 소환","d":"이 주문은 주문을 만들기 위해 사용된 정령의 잉걸불의 에너지를 가지고 있으며, 아군 정령을 소환해 싸울 수 있게 합니다! 한 번에 하나의 정령만 소환할 수 있지만, 주문을 소모하지 않고 다시 사용해 정령을 당신에게 되돌아오도록 지시할 수 있습니다.","img":"SUMMON_ELE"},{"p":"spells.ReclaimTrap","sub":"","n":"함정 흡수기","d":"이 주문은 DM-300 내부에 존재하던 기계 에너지를 담고 있습니다. 주문을 발동 가능한 함정에 시전하면, 그 함정의 힘이 당신에게 스며듭니다. 주문을 재시전 시 흡수한 함정의 효과를 원하는 장소에 발휘할 수 있게 합니다.\\n\\n그러나, 일부 함정은 어떤 곳에서는 작동하지 않을 수 있으며 주문은 한 번에 단 하나의 함정만 저장할 수 있습니다.","img":"RECLAIM_TRAP"}],"armor":[{"p":"armor.ClothArmor","sub":"armor","n":"천 갑옷","d":"이 가벼운 갑옷은 기본적인 보호를 제공합니다.","img":"ARMOR_CLOTH","t":1},{"p":"armor.LeatherArmor","sub":"armor","n":"가죽 갑옷","d":"그을려진 몬스터의 가죽으로 만든 갑옷입니다. 천 갑옷 만큼 가볍지는 않지만 훨씬 더 나은 보호 효과를 제공해 줍니다.","img":"ARMOR_LEATHER","t":2},{"p":"armor.MailArmor","sub":"armor","n":"사슬 갑옷","d":"금속 고리를 서로 엮어 만든 갑옷으로 단단하지만 유연한 갑옷입니다.","img":"ARMOR_MAIL","t":3},{"p":"armor.ScaleArmor","sub":"armor","n":"미늘 갑옷","d":"강철 미늘들이 가죽 조끼에 엮여져 유연하지만 견고한 갑옷을 만들었습니다.","img":"ARMOR_SCALE","t":4},{"p":"armor.PlateArmor","sub":"armor","n":"판금 갑옷","d":"거대한 철판들이 이어져 갑옷으로 만들어졌습니다. 이 갑옷의 엄청난 무게를 견딜 수 있는 모험가들에게 다른 갑옷과는 비교할 수도 없는 방어력을 제공해 줍니다.","img":"ARMOR_PLATE","t":5},{"p":"armor.AriaArmor","sub":"class","n":"AriaArmor","d":"","img":"ARMOR_ARIA","mod2":true},{"p":"armor.MageArmor","sub":"class","n":"영웅의 로브","d":"이 진귀한 로브를 입은 마법사는 특별한 능력을 사용할 수 있습니다.","img":"ARMOR_MAGE"},{"p":"armor.HuntressArmor","sub":"class","n":"영웅의 망토","d":"이 망토를 입은 사냥꾼은 특별한 능력을 사용할 수 있습니다.","img":"ARMOR_HUNTRESS"},{"p":"armor.ClericArmor","sub":"class","n":"영웅의 의례복","d":"이 천으로 덮인 판금 갑옷을 입은 성직자는 특별한 능력을 사용할 수 있습니다.","img":"ARMOR_CLERIC"},{"p":"armor.RogueArmor","sub":"class","n":"영웅의 의복","d":"이 어두운 의복을 입은 도적은 특별한 능력을 사용할 수 있습니다.","img":"ARMOR_ROGUE"},{"p":"armor.WarriorArmor","sub":"class","n":"영웅의 판금 갑옷","d":"이 무거운 갑옷을 입은 전사는 특별한 능력을 발휘할 수 있습니다.","img":"ARMOR_WARRIOR"},{"p":"armor.DuelistArmor","sub":"class","n":"영웅의 흉갑","d":"이 판금 갑옷과 망토를 착용하고 있으면, 결투자는 특별한 능력을 발휘할 수 있습니다.","img":"ARMOR_DUELIST"}],"key":[{"p":"keys.IronKey","sub":"","n":"쇠 열쇠","d":"이 고대의 쇠 열쇠에 새겨진 눈금은 많이 닳았습니다. 열쇠를 묶어 둔 가죽끈도 세월이 흘러 닳았습니다. 어떤 문을 열 수 있을까요?","img":"IRON_KEY"},{"p":"keys.CrystalKey","sub":"","n":"수정 열쇠","d":"이 수정 열쇠의 매끈한 표면은 어둠 속에서도 잘 보입니다. 수정으로 만들어진 잠금 장치를 열 수 있지 않을까요?","img":"CRYSTAL_KEY"},{"p":"keys.SkeletonKey","sub":"","n":"해골 열쇠","d":"이 열쇠는 장난이 아닙니다. 진짜로 손잡이가 해골 모양으로 되어 있거든요. 아마도 다음 지역으로 이동하는 문을 열 수 있을 것입니다.","img":"SKELETON_KEY"},{"p":"keys.GoldenKey","sub":"","n":"황금 열쇠","d":"이 황금 열쇠에 새겨진 눈금은 작고 정교합니다. 아마도 잠긴 상자를 열 수 있을 것 같습니다.","img":"GOLDEN_KEY"}],"potion":[{"p":"potions.PotionOfExperience","sub":"","n":"경험의 물약","d":"많은 사람들의 경험을 적은 이야기를 액체로 만든 것이며, 이 물약을 마시는 즉시 당신의 경험 레벨을 올릴 것입니다.","img":"POTION_HOLDER"},{"p":"potions.PotionOfParalyticGas","sub":"","n":"마비 가스의 물약","d":"이 용액이 공기에 노출되면 감각을 마비시키는 노란 안개로 기화하게 됩니다. 이 안개를 들이마시면 즉시 온 몸에 마비가 오게 되며, 구름이 사라진 후에도 얼마 동안은 움직일 수가 없게 됩니다. 던져서 먼 거리에 있는 적들에게 이 구름을 씌워 줄 수 있습니다.","img":"POTION_HOLDER"},{"p":"potions.PotionOfLevitation","sub":"","n":"부유의 물약","d":"이 호기심을 자아내는 물약을 마시면 공중으로 떠오르게 됩니다. 당신은 공중을 별 어려움 없이 떠다닐 수 있으며 함정과 구덩이를 넘어다닐 수 있습니다. 물약을 던지면 정제되지 않은 가스를 내뿜어 가스를 들이마신 대상의 방향 감각을 상실시킵니다.","img":"POTION_HOLDER"},{"p":"potions.PotionOfFrost","sub":"","n":"서리의 물약","d":"이 화합물은 공기에 닿는 즉시 차가운 구름으로 기화합니다.","img":"POTION_HOLDER"},{"p":"potions.PotionOfHaste","sub":"","n":"신속의 물약","d":"매우 달콤한 이 물약은 당신에게 폭발적인 에너지를 부여해 짧은 시간 동안 매우 빠른 속도로 달릴 수 있게 합니다.","img":"POTION_HOLDER"},{"p":"potions.PotionOfMindVision","sub":"","n":"심안의 물약","d":"이 용액을 마시면, 당신의 생각은 잠시 동안 근처의 생물체들의 정신적인 흔적과 동화됩니다. 그래서 벽 너머로 생명체를 탐지할 수 있고, 문이나 벽 너머로 무엇이 있는지 볼 수 있습니다.","img":"POTION_HOLDER"},{"p":"potions.PotionOfLiquidFlame","sub":"","n":"액체 화염 물약","d":"이 물병은 불안정한 화합물로 가득 차 있어 공기와 닿으면 급격한 폭발을 일으키며 주변을 불로 뒤덮습니다.","img":"POTION_HOLDER"},{"p":"potions.PotionOfToxicGas","sub":"","n":"유독 가스의 물약","d":"이 유리병을 열거나 깨는 순간 내용물이 폭발하여 녹색의 유독성 구름을 남깁니다. 손으로 개봉하는 대신 멀리 있는 적들에게 던질 수 있습니다.","img":"POTION_HOLDER"},{"p":"potions.PotionOfPurity","sub":"","n":"정화의 물약","d":"이 마법 용액은 넓은 구역 내의 모든 해로운 범위효과를 빠르게 정화시킵니다. 마시면 해당 효과들에 대해 잠시동안 면역이 됩니다.","img":"POTION_HOLDER"},{"p":"potions.PotionOfHealing","sub":"","n":"치유 물약","d":"이 회복약은 체력을 급속도로 회복시키며 많은 상태 이상을 치료합니다.","img":"POTION_HOLDER"},{"p":"potions.PotionOfInvisibility","sub":"","n":"투명화의 물약","d":"이 물약을 마시면 일시적으로 투명해집니다. 투명해진 상태에서는 적들이 당신을 볼 수 없습니다. 물리적인 공격을 하거나 (주문서나 마법 막대와 같은) 마법 효과를 발동시킨다면 그 즉시 투명 효과가 사라질 것입니다.","img":"POTION_HOLDER"},{"p":"potions.PotionOfStrength","sub":"","n":"힘의 물약","d":"이 강력한 용액은 당신의 근육을 타고 흘러, 당신의 힘을 1만큼 영구적으로 늘립니다.","img":"POTION_HOLDER"},{"p":"potions.brews.BlizzardBrew","sub":"brew","n":"눈보라 혼합물","d":"이 혼합물은 깨지는 순간 가스처럼 빠르게 퍼져나가는 매서운 눈보라를 방출할 것입니다.","img":"BREW_BLIZZARD"},{"p":"potions.brews.AquaBrew","sub":"brew","n":"물 혼합물","d":"이 혼합물이 깨지면 그 위치에 고압의 물을 폭발시킵니다. 이 물로 인해 직접적인 피해를 입게 되는 것은 불로 이루어진 적들 뿐이지만, 주변 지형에 물을 흩뿌리고, 함정을 무력화하며, 불을 끄고, 폭발의 중심 근처에 있는 모든 캐릭터를 밀쳐냅니다.","img":"BREW_AQUA"},{"p":"potions.brews.UnstableBrew","sub":"brew","n":"불안정한 혼합물","d":"이 마법의 혼합물은 일곱 빛깔로 변화하며 빛나고 있습니다.\\n\\n이것을 마시거나 던지면 무작위 물약의 효과를 발동시킬 것입니다. 물약의 효과는 마시면 항상 이로운 효과가 되며, 던지면 항상 해로운 효과가 될 것입니다.","img":"BREW_UNSTABLE"},{"p":"potions.brews.CausticBrew","sub":"brew","n":"산성 혼합물","d":"이 혼합물은 깨진 지점을 중심으로 산성 점액을 넓게 흩뿌립니다. 점액을 뒤집어 쓴 대상은 물에서 씻어내기 전까지 몸이 서서히 녹을 것입니다.","img":"BREW_CAUSTIC"},{"p":"potions.brews.ShockingBrew","sub":"brew","n":"전격 혼합물","d":"이 혼합물은 깨지는 순간 주변 넓은 지역에 강력한 전기 폭풍을 방출할 것입니다.","img":"BREW_SHOCKING"},{"p":"potions.brews.InfernalBrew","sub":"brew","n":"지옥불 혼합물","d":"이 혼합물은 깨지는 순간 가스처럼 빠르게 퍼져나가는 뜨거운 용암을 방출할 것입니다.","img":"BREW_INFERNAL"},{"p":"potions.elixirs.ElixirOfHoneyedHealing","sub":"elixir","n":"달달한 치유 영약","d":"이 영약은 치유 물약과 달콤한 꿀을 섞어 만들었으며, 마시면 치유 물약의 효과와 함께 약간의 허기를 회복하며, 동료를 치유하는 데에도 사용될 수 있습니다.\\n\\n만약 꿀과 친밀감이 있는 생물체에게 사용될 경우 그것을 진정시킬 것입니다.","img":"ELIXIR_HONEY"},{"p":"potions.elixirs.ElixirOfToxicEssence","sub":"elixir","n":"독성 정수의 영약","d":"이 영약은 사용자에게 독성 에너지와 동화할 수 있는 힘을 제공합니다. 영약을 마시게 되면 사용자는 이동할 때마다 지속적으로 주변에 유독성 가스를 내뿜으며, 동화 효과보다 조금 더 긴 시간 동안 유독성 가스와 중독에 면역이 됩니다.","img":"ELIXIR_TOXIC"},{"p":"potions.elixirs.ElixirOfAquaticRejuvenation","sub":"elixir","n":"수상 회복의 영약","d":"이 영약은 치유 물약에 구의 조각을 섞어 향상시킨 것입니다. 이 영약은 즉각적인 치유 효과를 주진 않지만, 대신 물 위에 서 있을 때 지속적으로 더욱 많은 양의 치유 효과를 줍니다.","img":"ELIXIR_AQUA"},{"p":"potions.elixirs.ElixirOfArcaneArmor","sub":"elixir","n":"신비한 갑옷 영약","d":"이 영약은 마신 사람에게 오랫동안 지속되는 마법 저항 효과를 부여합니다.","img":"ELIXIR_ARCANE"},{"p":"potions.elixirs.ElixirOfFeatherFall","sub":"elixir","n":"안전한 착지의 영약","d":"이 영약은 사용자에게 약하지만 조금 더 조정된 부유 효과를 부여하여, 짧은 시간 동안 높은 곳에서 떨어질 때에 큰 피해를 받지 않도록 합니다.","img":"ELIXIR_FEATHER"},{"p":"potions.elixirs.ElixirOfMight","sub":"elixir","n":"용력의 영약","d":"이 강력한 용액은 당신의 근육을 타고 흘러, 영구적으로 1만큼의 힘을, 일시적으로 %d 만큼의 최대 체력을 늘립니다. 이 체력 증가량은 당신의 최대 체력에 따라 결정되나, 이렇게 얻은 최대 체력은 레벨을 올릴수록 천천히 감소할 것입니다.","img":"ELIXIR_MIGHT"},{"p":"potions.elixirs.ElixirOfDragonsBlood","sub":"elixir","n":"용의 피 영약","d":"이 영약을 마시는 순간 음용자의 정맥에 맹렬한 힘을 흘려보낼 것입니다. 이 효과는 음용자가 화염에 면역을 갖도록 하며, 물리적 공격에 적을 불태워버릴 수 있는 힘을 실어보낼 것입니다.","img":"ELIXIR_DRAGON"},{"p":"potions.elixirs.ElixirOfIcyTouch","sub":"elixir","n":"차가운 숨결 영약","d":"이 물약을 마시면 당신이 공격하는 적들로부터 열기를 빼앗아 올 수 있게 됩니다. 이 효과는 당신을 추위에 면역으로 만들어 줄 것이며 물리적 공격으로 적들을 얼릴 수 있게 만들어 줄 것입니다.","img":"ELIXIR_ICY"},{"p":"potions.exotic.PotionOfEarthenArmor","sub":"exotic","n":"돌 갑옷의 물약","d":"더 이상 마비시키지는 않지만, 이 용액은 잠시 동안 신체를 돌로 감싸서 방어력을 증가시킵니다.","img":"POTION_HOLDER"},{"p":"potions.exotic.PotionOfMagicalSight","sub":"exotic","n":"마법 시야의 물약","d":"이 물약을 마시면 당신의 감각이 짧은 시간동안 무지막지한 정도로 상승하여 시야가 확장되며, 무려 벽 너머로 12타일까지 볼 수 있습니다!","img":"POTION_HOLDER"},{"p":"potions.exotic.PotionOfShielding","sub":"exotic","n":"보호막의 물약","d":"사용자를 치유하지는 않는 대신, 이 물약은 지속되는 동안 사용자의 몸에 상당한 피해를 막아낼 수 있는 보호막을 두를 것입니다.","img":"POTION_HOLDER"},{"p":"potions.exotic.PotionOfCorrosiveGas","sub":"exotic","n":"부식 가스의 물약","d":"이 물약을 열거나 깨는 순간 내용물이 폭발하여 치명적인 부식 가스가 방출됩니다. 부식 가스는 일반적인 유독 가스보다 더욱 치명적이며, 더 빠르게 퍼져나가지만, 그리 오래 지속되지는 않습니다.","img":"POTION_HOLDER"},{"p":"potions.exotic.PotionOfMastery","sub":"exotic","n":"숙련의 물약","d":"힘 그 자체를 얻는 대신, 이 물약은 사용자의 근육을 특정 장비 하나에 맞게 조율합니다. 이를 통해 사용자는 그 장비를 수없이 사용해 온 것처럼 손쉽게 다룰 수 있게 됩니다.\\n\\n선택된 무기 혹은 방어구의 힘 요구 수치가 2 감소할 것입니다. 이 물약은 각 장비에 대해 한 번씩만 사용할 수 있습니다.","img":"POTION_HOLDER"},{"p":"potions.exotic.PotionOfSnapFreeze","sub":"exotic","n":"순간 빙결 물약","d":"이 물약에 들은 화합물은 공기와 격렬하게 반응하여 주변을 빙결시키고 구속시킵니다.","img":"POTION_HOLDER"},{"p":"potions.exotic.PotionOfDivineInspiration","sub":"exotic","n":"신성한 영감의 물약","d":"신성한 힘을 액체 형태로 농축한 것으로, 이것을 마시면 신성한 힘이 깃들어 원하는 특성 티어에 2개의 추가 특성 포인트를 제공할 것입니다.\\n\\n이 물약은 각 특성 티어 당 한 번씩만 사용할 수 있습니다.","img":"POTION_HOLDER"},{"p":"potions.exotic.PotionOfShroudingFog","sub":"exotic","n":"연막 물약","d":"이 플라스크에 든 용액은 짙은 연기로 된 안개를 빠르게 퍼뜨려 적들의 시야를 차단합니다.","img":"POTION_HOLDER"},{"p":"potions.exotic.PotionOfDragonsBreath","sub":"exotic","n":"용 숨결의 물약","d":"이 물병엔 입속의 침과 반응하여 불꽃을 일으키는 용액이 들어 있습니다. 빠르게 이 용액을 뱉어내면 마치 사용자가 불길을 내뿜는 것처럼 할 수 있습니다!","img":"POTION_HOLDER"},{"p":"potions.exotic.PotionOfStamina","sub":"exotic","n":"지구력의 물약","d":"매우 달콤한 이 물약은 당신에게 폭발적인 에너지를 부여해 긴 시간 동안 매우 빠른 속도로 달릴 수 있게 합니다.","img":"POTION_HOLDER"},{"p":"potions.exotic.PotionOfCleansing","sub":"exotic","n":"청정의 물약","d":"이 강력한 용액을 마시면 몇 턴 간 모든 해로운 상태 효과에 면역이 됩니다. 혹은 목표물에게 던져 대상을 정화하는 데에도 사용할 수 있습니다.","img":"POTION_HOLDER"},{"p":"potions.exotic.PotionOfStormClouds","sub":"exotic","n":"폭풍우 물약","d":"이 물약을 던지면 던진 지역에 빠르게 퍼져나가는 폭풍을 생성합니다. 폭우가 내려 대부분의 바닥은 물로 바뀌며, 불로 이루어진 적에게 큰 피해를 주며, 불이 꺼지고, 함정은 고장나 작동을 정지합니다.","img":"POTION_HOLDER"}],"artifact":[{"p":"artifacts.CapeOfThorns","sub":"","n":"가시 망토","d":"DM-300에서 떨어져 나온 뭉개진 철판이 망토의 모습으로 변하였습니다. 이것은 강력한 에너지를 담고 있는 것처럼 보입니다. 아마도 DM-300의 힘을 담고 있지 않을까요?","img":"ARTIFACT_CAPE"},{"p":"artifacts.CloakOfShadows","sub":"","n":"그림자의 망토","d":"몇년 전 도적이 왕국의 무기고에서 훔쳐 낸 진귀한 마법 망토입니다. 이 망토를 입으면 일시적으로 완전히 투명해질 수 있습니다.\\n\\n망토를 사용하면 할 수록, 효과가 더욱 강해집니다. 그리하여 도적은 더 자주, 더 오래 투명화할 수 있습니다.","img":"ARTIFACT_CLOAK"},{"p":"artifacts.MasterThievesArmband","sub":"","n":"대도의 팔찌","d":"이 보라색 벨벳 팔찌에는 대도의 표식이 새겨져 있습니다. 이것은 당신의 소유가 아니지만, 원래 주인도 또 다른 사람에게서 빼앗았을 것입니다.","img":"ARTIFACT_ARMBAND"},{"p":"artifacts.LloydsBeacon","sub":"","n":"로이드의 신호기","d":"로이드의 신호기는 사용자에게 공간이동 마법을 제어할 수 있는 정교한 마법 장치입니다. 신호기에 원하는 위치를 등록 시켜 돌아갈 수도 있지만, 장비한 상태에서 충전량을 소모하여 무작위 공간이동 마법을 발사할 수 있습니다. 이 마법은 대상에게 사용하거나 자신에게도 사용할 수 있습니다.","img":"ARTIFACT_BEACON"},{"p":"artifacts.DriedRose","sub":"","n":"메마른 장미","d":"과연 이 장미가 슬픈 유령이 성불하기 직전에 이야기했던 물건일까요? 이 장미엔 영적인 힘을 붙드는 힘이 있어, 쓰러진 전사의 영혼을 모을 수 있을 것 같습니다.","img":"ARTIFACT_ROSE1"},{"p":"artifacts.UnstableSpellbook","sub":"","n":"불안정한 마법책","d":"이 마법책은 오래된 것임에도 불구하고 놀랍도록 새 것같이 느껴집니다. 페이지를 넘길 때마다 불안정한 에너지로 종이가 떨리고 있습니다. 당신이 이 책을 읽을 때, 어떤 주문이 시전될 것인지는 아무도 모릅니다.","img":"ARTIFACT_SPELLBOOK"},{"p":"artifacts.HolyTome","sub":"","n":"성서","d":"성직자는 성서를 매개로 신성력을 발휘합니다. 성서를 사용하면 여러 가지 마법 주문을 시전할 수 있습니다.\\n\\n성직자가 성서를 사용할수록 더욱 강력해집니다. 최대 충전 수가 증가하며 충전 속도가 약간 더 빨라집니다.","img":"ARTIFACT_TOME"},{"p":"artifacts.TimekeepersHourglass","sub":"","n":"시간군주의 모래시계","d":"이 거대하고 화려한 모래시계는 그렇게 눈에 띄지는 않지만, 아름답게 조각된 몸체에서 엄청난 힘이 느껴집니다. 모래시계를 뒤집어 모래가 흐르는 것을 보면 시간을 다룰 수 있는 마법을 얻게 됩니다.","img":"ARTIFACT_HOURGLASS"},{"p":"artifacts.EtherealChains","sub":"","n":"에테르 사슬","d":"이 거대하지만 매우 가벼운 사슬은 영적인 에너지로 빛이 납니다. 멀리 있는 벽에 걸어 당신이 이동할 수도 있고, 적을 당신에게로 끌어올 수도 있습니다. 사슬의 영적인 힘은 벽을 넘어서도 사슬을 걸 수 있게 해 줍니다!","img":"ARTIFACT_CHAINS"},{"p":"artifacts.AlchemistsToolkit","sub":"","n":"연금술사의 도구상자","d":"이 도구 상자는 이동 중에도 연금술을 할 수 있도록 작은 혼합 병과 함께 다양한 시약 병을 담고 있습니다. 옆에 달려 있는 유리병에는 연금술 에너지 수정이 액체의 형태로 담겨 있는 것처럼 보입니다.","img":"ARTIFACT_TOOLKIT"},{"p":"artifacts.TalismanOfForesight","sub":"","n":"예지의 부적","d":"특이한 문양이 새겨진 매끈한 돌멩이입니다. 당신 주변의 모든 것을 감시하는 것 처럼 보이며, 숨겨진 모든 것에 주시하는 듯 합니다.","img":"ARTIFACT_TALISMAN"},{"p":"artifacts.SandalsOfNature","sub":"","n":"자연의 샌들","d":"","img":"ARTIFACT_SANDALS"},{"p":"artifacts.HornOfPlenty","sub":"","n":"풍요의 뿔","d":"이 뿔피리는 불 수는 없지만, 착용한 후 경험치를 얻음에 따라 음식을 만들어내는 것 같습니다. 당신은 각각의 충전량을 간식으로 사용해 먹거나 배부를 때까지 전부 먹을 수도 있습니다.","img":"ARTIFACT_HORN1"},{"p":"artifacts.ChaliceOfBlood","sub":"","n":"피의 성배","d":"이 빛나는 은색 성배의 테두리에는 뾰족한 보석들로 둘러져 있습니다.","img":"ARTIFACT_CHALICE1"}],"codex":[{"p":"weapon.codices.cast.SanctuaryManaField","sub":"cast","n":" 생츄어리 마나 필드 코덱스","d":" 생츄어리 마나 필드 코덱스 설명","img":"CODEX_MANAFIELD","t":5,"mod2":true},{"p":"weapon.codices.melee.MagicImageAnimator","sub":"melee","n":"MagicImageAnimator","d":"","img":"SOMETHING","mod2":true},{"p":"weapon.codices.melee.MagicGavel","sub":"melee","n":"매직 개벨 코덱스","d":"차징(1~5턴)으로 힘을 모은 뒤, 전방 바로 앞 1타일을 중심으로 3×3 범위를 내려찍습니다. 차징 중에는 이동할 수 없습니다.","img":"CODEX_GAVEL","t":1,"mod2":true},{"p":"weapon.codices.melee.MagicRampage","sub":"melee","n":"매직 램페이지 코덱스","d":"반경 %1$d타일 이내의 좌표를 지정하고, 그 지점까지 직선으로 돌진하며 경로상의 모든 적들을 꿰뚫습니다.","img":"CODEX_RAMPAGE","t":1,"mod2":true},{"p":"weapon.codices.melee.MagicSlash","sub":"melee","n":"매직 슬래시 코덱스","d":"지정한 방향으로 2연속의 마법 참격을 가합니다. 전방 1타일에 있는 적을 벤 뒤, 2타일째에 적이 없다면 같은 대상을 한 번 더 찌릅니다.","img":"CODEX_SLASH","t":1,"mod2":true},{"p":"weapon.codices.melee.MagicShieldBash","sub":"melee","n":"매직 실드배쉬 코덱스","d":"마법으로 된 방패로 타격을 가합니다. 전방 1타일의 적을 지정 후, 해당 방향의 2타일까지의 적들에게 넉백과 스턴을 부여합니다.","img":"CODEX_SHIELD_S","t":1,"mod2":true},{"p":"weapon.codices.ranged.MagicBullet","sub":"ranged","n":"매직 불릿 코덱스","d":"대상에게 _3연속_ 마탄을 발사합니다. 첫 타격 후 동일 대상에게 나머지 타격이 즉시 이어지며,  대상이 중간에 쓰러지면 연사가 종료됩니다.","img":"CODEX_BULLET","t":1,"mod2":true},{"p":"weapon.codices.ranged.MagicArrow","sub":"ranged","n":"매직 애로우 코덱스","d":"대상에게 _5연속_ 마법 화살을 쏩니다. 첫 타격 후 동일 대상에게 나머지 타격이 짧은 간격으로 이어지며,  대상이 중간에 쓰러지면 연사가 종료됩니다.","img":"CODEX_ARROW","t":2,"mod2":true},{"p":"weapon.codices.ranged.MagicMissile","sub":"ranged","n":"매직 미사일 코덱스","d":"단일 대상에게 강한 마력 미사일을 발사합니다.","img":"CODEX_MISSILE","t":3,"mod2":true},{"p":"weapon.codices.ranged.MagicCannon","sub":"ranged","n":"매직 캐논 코덱스","d":"대상 명중 시 폭발을 일으켜 _3×3_ 범위의 주변 적에게 명중 대상에게 입힌 기본 피해의 약 절반의 추가 피해를 줍니다.","img":"CODEX_CANNON","t":4,"mod2":true},{"p":"weapon.codices.ranged.MagicSingularity","sub":"ranged","n":" 마법의 특이점 코덱스","d":"명중 지점을 기준으로 _7×7_의 대폭발을 일으킵니다. 이어서 _5턴_ 동안 ‘중력장’을 전개하여 범위 내 적에게 매턴 피해를 주고, 매턴 중심으로 1타일씩 끌어당깁니다.","img":"CODEX_SINGULARITY","t":5,"mod2":true}]};
